-- daytime-caffeine-sleep
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('2f0cc739-d18b-5ca3-9981-5971623614e9', 'daytime-caffeine-sleep', 'Caffeine three times a day, the last dose 8 hours before bed: what the sleep lab recorded', '10.1038/s41598-021-84088-x', 'Sleep', 'Twenty young men who drink caffeine every day took 150 mg three times a day, the last dose 8 hours before bed. Their measured sleep did not differ from their placebo nights. One thing in the brain recordings did.', 'free', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('2f0cc739-d18b-5ca3-9981-5971623614e9', '{"hook":[{"text":"The usual advice is to stop caffeine by noon.","refs":[]},{"text":"A sleep laboratory tested something closer to how people actually take it: morning, midday and mid-afternoon, every day.","refs":["schedule"]}],"populationPanel":[{"text":"Who was studied: twenty healthy men aged 18 to 35 who already had 300 to 600 mg of caffeine a day and slept well.","refs":["sample","who","good_sleepers"]},{"text":"Each man went through all three conditions in random order without knowing which capsules he was taking.","refs":["blind"]},{"text":"The result describes men like these.","refs":["lim_male"]},{"text":"It says nothing yet about women, older adults or people who rarely have caffeine.","refs":["lim_male","lim_young","not_after_abstinence"]}],"sections":[],"limitations":[],"layers":{"mechanism":{"paragraphs":[[{"text":"All day, a tiredness signal collects in your brain.","refs":["concept:adenosine"]},{"text":"It settles onto brain cells and slows them down, so you feel sleepy.","refs":["concept:adenosine"]},{"text":"Caffeine takes its parking spot.","refs":["adenosine_block"]},{"text":"The signal is still there; it just cannot land.","refs":["adenosine_block"]},{"text":"Its name is adenosine.","refs":["adenosine_block"]}],[{"text":"Late in the day, that block can cost you sleep.","refs":["evening"]},{"text":"Earlier studies found that evening caffeine made sleep slower to come and shorter, with less deep sleep.","refs":["evening"]}],[{"text":"A daily habit changes the picture.","refs":["tolerance"]},{"text":"In earlier work the authors cite, a week of regular caffeine blunted its effect on sleep, even with large evening doses.","refs":["tolerance"]},{"text":"That fits what this trial saw.","refs":[]},{"text":"On caffeine, measured sleep showed no clear difference from placebo nights.","refs":["sleep_same"]}],[{"text":"The authors also suggest a daily loop.","refs":["daily_reverse"]},{"text":"Each night, as the last dose wears off, a small withdrawal may begin.","refs":["sigma_meaning"]},{"text":"The first dose next morning would undo it.","refs":["daily_reverse"]}]],"figure":{"figure":"parking-spot","headline":[{"text":"Caffeine takes the tiredness signal’s parking spot.","refs":["adenosine_block"]}],"caption":[{"text":"Dashed: how the authors describe caffeine acting, not measured in this study.","refs":["adenosine_block"]},{"text":"Dotted: a sketch of the tiredness signal building up, not data.","refs":[]}],"alt":"Two panels, each showing the surface of a brain cell with one cup-shaped dock. Without caffeine, round tokens, the tiredness signal, drift down and one sits in the dock: you feel sleepy. With caffeine, a hexagon, caffeine, sits in the dock; the round tokens crowd above it and cannot land: you feel alert. How many tokens are drawn means nothing; they are a sketch, not data.","params":{"title":"Caffeine in the tiredness signal’s dock","tokens":{"sketch":"tiredness-tokens","concept":"adenosine","tag":"Sketch, not data","ink":"muted","labels":{"signal":"Tiredness signal (adenosine). It builds up while you are awake."},"alt":"Small round tokens drawn with dotted outlines: a sketch of the tiredness signal building up, not data. How many are drawn means nothing."},"block":{"tag":"How the authors describe it, not measured in this study","kind":"proposed","fact":{"id":"adenosine_block","kind":"context","label":"How caffeine acts, as the authors describe it: it blocks adenosine receptors and may hold back sleep pressure","quote":"Caffeine is an adenosine receptor antagonist, which blocks the Aand Aadenosine receptors in the central nervous system. It may, thus, attenuate the increase in sleep pressure during wakefulness"}},"without":{"title":"Without caffeine","dock":"The dock on a brain cell","feeling":{"lead":"Signal lands. You feel","word":"sleepy","end":"."}},"with":{"title":"With caffeine","caffeine":"Caffeine","dock":"Caffeine sits in the dock","crowd":"The signal is still there. It just can’t land.","feeling":{"lead":"You feel","word":"alert","end":"."}}}}},"protocol":{"paragraphs":[[{"text":"For 10 days, the men took a capsule three times a day: 45, 255 and 475 minutes after waking.","refs":["schedule"]},{"text":"In one condition every capsule held 150 mg of caffeine; in another, every capsule was a placebo.","refs":["dose"]},{"text":"The third switched from caffeine to placebo after 8 days.","refs":["dose"]}],[{"text":"After 9 days, they slept in the laboratory with sensors on the scalp recording the brain.","refs":["recording"]},{"text":"On caffeine, the night began 8 hours after the last capsule.","refs":["recording"]},{"text":"The trial did not try a last dose closer to bed.","refs":["recording"]}]],"figure":{"figure":"hidden-tiredness","headline":[{"text":"Caffeine hides tiredness.","refs":[]},{"text":"It doesn’t remove it.","refs":[]}],"caption":[{"text":"Dotted: a sketch of tiredness through the day, not data.","refs":[]},{"text":"The day runs from waking to bed, with the study’s three doses and the 8 hours to the sleep recording.","refs":["schedule","recording"]},{"text":"The box is what the sleep laboratory found.","refs":["sleep_same"]}],"alt":"Two dotted lines run from waking to bed. One, sleep pressure, keeps rising. The other, how tired you feel, follows it until the first dose, then runs below it. The hatched gap between them is hidden tiredness, and it narrows towards bed without closing. Nothing is drawn after bed. A box beneath says what the study found: sleep showed no clear difference from placebo nights.","params":{"title":"Tiredness through a caffeine day, and what the sleep laboratory found","tiredness":{"sketch":"sleep-pressure","concept":"adenosine","tag":"Sketch, not data","ink":"ink","labels":{"panel":"Two kinds of tiredness","pressure":"Sleep pressure keeps building","felt":"How tired you feel","gap":"Hidden tiredness","narrows":"The gap narrows as caffeine fades"},"alt":"Two dotted lines through a waking day: a sketch of sleep pressure building and of how tired you feel, not data. Their heights and the gap are not from the paper."},"day":{"wake":"wake","bed":"bed"},"doses":{"times":[{"n":45,"ref":"schedule"},{"n":255,"ref":"schedule"},{"n":475,"ref":"schedule"}],"lead":"The study’s doses:","amount":{"text":"150 mg","ref":"dose"},"rest":"three times a day"},"recording":{"lead":"Sleep recording began","hours":{"n":8,"ref":"recording"},"rest":"hours after the last dose"},"phases":["first dose","in effect","fading"],"found":{"title":"What this study found","finding":"Sleep showed no clear difference from placebo nights.","kind":"measured","fact":{"id":"sleep_same","kind":"finding","label":"no clear difference from placebo; the paper does not say how big any difference was","quote":"the analyses of the polysomnography (PSG) did not reveal significant differences in total sleep time (TST), sleep efficiency (SE), sleep latencies, or the relative amount of sleep stages among the three conditions (> 0.05)","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total sleep time, time to fall asleep and sleep stages","tier":"low"}},"who":{"lead":"Twenty men aged","from":{"n":18,"ref":"who"},"to":{"n":35,"ref":"who"},"rest":"who drink caffeine every day."}}}},"figureSlot":"try"},"audit":{"effect":[{"text":"The paper checked total sleep, time to fall asleep and the share of each sleep stage.","refs":["sleep_same"]},{"text":"For each, it reports no clear difference between conditions, with p above 0.05.","refs":["sleep_same"]},{"text":"It gives no size for any of these differences.","refs":["sleep_same"]}],"weakEnd":[{"text":"The paper gives no confidence interval for these results.","refs":["sleep_same"]},{"text":"With twenty men, a real difference of a few minutes could hide inside “no clear difference”.","refs":["sample","lim_n"]},{"text":"Read it as no large disruption found in this group, not proof that there is none.","refs":["sleep_same"]}],"limitations":[[{"text":"Only men took part, so the result may not hold for women.","refs":["lim_male"]}],[{"text":"Everyone was 18 to 35.","refs":["who"]},{"text":"The authors say middle-aged people are more sensitive to what caffeine does to sleep.","refs":["lim_young"]}],[{"text":"Twenty men make a small trial.","refs":["sample","lim_n"]},{"text":"Without effect sizes, nobody can say how small a difference it could have missed.","refs":["lim_n"]}]],"missed":[{"text":"One measure did change.","refs":[]},{"text":"A band of the brain’s electrical activity in sleep, called sigma, was lower on caffeine nights than on placebo nights.","refs":["sigma"]},{"text":"The authors read it as early withdrawal, already there 8 hours after the last dose.","refs":["sigma_meaning"]}],"more":[[{"text":"At home, the men went to bed about 25 minutes later on caffeine than on placebo.","refs":["later_bed"]}],[{"text":"Their own ratings of how they slept showed no clear difference between conditions either.","refs":["quality_same"]}],[{"text":"The researchers expected less deep sleep on caffeine and did not find it.","refs":["no_depth_change"]}],[{"text":"The authors warn that morning caffeine could still disturb sleep after several days without any.","refs":["not_after_abstinence"]}]],"figure":null}},"glossary":[{"term":"adenosine","plain":"A tiredness signal made in the brain. It builds up the longer you stay awake, as brain cells burn energy. When it settles onto brain cells it slows them down, and you feel sleepy. Sleep clears it away.","refs":[],"concept":"adenosine"},{"term":"placebo","plain":"A capsule that looked the same as the caffeine one but held no caffeine.","refs":["capsules"],"concept":null}],"primaryEstimate":"sleep_same","finding":{"question":[{"text":"Does an afternoon coffee wreck your sleep?","refs":["schedule"]}],"headline":[{"text":"Sleep showed no clear difference from placebo nights.","refs":["sleep_same"]}],"support":[{"text":"Total sleep, time to fall asleep and sleep stages were all checked.","refs":["sleep_same"]}]},"simulator":{"kind":"decay","params":{},"spec":{"kind":"decay","facts":{"halfLife":{"id":"caffeine-saliva-half-life/half_life_caffeine","kind":"estimate","label":"Caffeine half-life in saliva after a single 25 mg dose (arm A), mean ± SD, n = 12","quote":"Caffeine showed a half-life of 5.15 ± 1.21 h after single administration, whereas the half-life of methylliberine was only 1.15 ± 0.12 h and that of theacrine 21.00 ± 7.55 h.","source":"caffeine-saliva-half-life","why":"People were assigned at random, but only 12 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Elimination half-life of caffeine in saliva after 25 mg taken alone (arm A)","measure":"mean","point":5.15,"ciLow":null,"ciHigh":null,"unit":"h","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":1.21}}},"simulator":{"halfLife":{"id":"caffeine-saliva-half-life/half_life_caffeine","kind":"estimate","label":"Caffeine half-life in saliva after a single 25 mg dose (arm A), mean ± SD, n = 12","quote":"Caffeine showed a half-life of 5.15 ± 1.21 h after single administration, whereas the half-life of methylliberine was only 1.15 ± 0.12 h and that of theacrine 21.00 ± 7.55 h.","source":"caffeine-saliva-half-life","why":"People were assigned at random, but only 12 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Elimination half-life of caffeine in saliva after 25 mg taken alone (arm A)","measure":"mean","point":5.15,"ciLow":null,"ciHigh":null,"unit":"h","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":1.21}}}},"words":{"alt":[{"text":"A falling curve shows how much of a dose of caffeine is left in the hours after you take it.","refs":["caffeine-saliva-half-life/half_life_caffeine"]},{"text":"A shaded band around the curve shows how much people in that study differed.","refs":["caffeine-saliva-half-life/half_life_caffeine"]}],"halfLifeNote":[{"text":"That half-life comes from another study: twelve young volunteers took 25 mg of caffeine on its own, measured in their saliva.","refs":["caffeine-saliva-half-life/crossover_design","caffeine-saliva-half-life/arm_a_dose","caffeine-saliva-half-life/matrix_saliva"]}],"finding":[{"text":"In this paper, men who had caffeine every day took their last 150 mg dose 8 hours before bed.","refs":["sample","who","dose","recording"]},{"text":"Their measured sleep did not differ from their placebo nights.","refs":["sleep_same"]}]}},"glance":{"figure":{"figure":"hidden-tiredness","headline":[{"text":"Caffeine hides tiredness.","refs":[]},{"text":"It doesn’t remove it.","refs":[]}],"caption":[],"alt":"Two dotted lines from waking to bed: sleep pressure keeps rising, and how tired you feel runs below it after the first dose, a gap called hidden tiredness. Beneath, the study found no clear difference in sleep.","params":{"title":"Tiredness through a caffeine day, and what the sleep laboratory found","tiredness":{"sketch":"sleep-pressure","concept":"adenosine","tag":"Sketch, not data","ink":"ink","labels":{"panel":"Two kinds of tiredness","pressure":"Sleep pressure keeps building","felt":"How tired you feel","gap":"Hidden tiredness","narrows":"The gap narrows as caffeine fades"},"alt":"Two dotted lines through a waking day: a sketch of sleep pressure building and of how tired you feel, not data. Their heights and the gap are not from the paper."},"day":{"wake":"wake","bed":"bed"},"doses":{"times":[{"n":45,"ref":"schedule"},{"n":255,"ref":"schedule"},{"n":475,"ref":"schedule"}],"lead":"The study’s doses:","amount":{"text":"150 mg","ref":"dose"},"rest":"three times a day"},"recording":{"lead":"Sleep recording began","hours":{"n":8,"ref":"recording"},"rest":"hours after the last dose"},"phases":["first dose","in effect","fading"],"found":{"title":"What this study found","finding":"Sleep showed no clear difference from placebo nights.","kind":"measured","fact":{"id":"sleep_same","kind":"finding","label":"no clear difference from placebo; the paper does not say how big any difference was","quote":"the analyses of the polysomnography (PSG) did not reveal significant differences in total sleep time (TST), sleep efficiency (SE), sleep latencies, or the relative amount of sleep stages among the three conditions (> 0.05)","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total sleep time, time to fall asleep and sleep stages","tier":"low"}},"who":{"lead":"Twenty men aged","from":{"n":18,"ref":"who"},"to":{"n":35,"ref":"who"},"rest":"who drink caffeine every day."}}}},"x":[{"text":"Your waking day","refs":[]}],"y":[],"alt":[{"text":"Two dotted lines from waking to bed: sleep pressure keeps rising, and how tired you feel runs below it after the first dose, a gap called hidden tiredness.","refs":["schedule"]},{"text":"Beneath, the study found no clear difference in sleep.","refs":["sleep_same"]}],"note":[{"text":"The tiredness lines are a sketch, not data. Try it with your own coffee inside.","refs":[]}],"tryIt":[{"text":"how much is left at your bedtime","refs":[]}]},"sourceLine":"Twenty healthy young men · randomized crossover trial · 10 days per condition","facts":{"adenosine_block":{"id":"adenosine_block","kind":"context","label":"How caffeine acts, as the authors describe it: it blocks adenosine receptors and may hold back sleep pressure","quote":"Caffeine is an adenosine receptor antagonist, which blocks the Aand Aadenosine receptors in the central nervous system. It may, thus, attenuate the increase in sleep pressure during wakefulness"},"blind":{"id":"blind","kind":"context","label":"Trial design","quote":"We employed a double-blind, randomized, crossover study including a caffeine, a withdrawal, and a placebo condition."},"caffeine-saliva-half-life/arm_a_dose":{"id":"caffeine-saliva-half-life/arm_a_dose","kind":"context","label":"Dose and capsule count in study arm A","quote":"Then, the ice capsules (study arm A: 25 mg caffeine, study arm B: 100 mg methylliberine, study arm C: 50 mg theacrine, study arm D: combination of 25 mg caffeine, 100 mg methylliberine and 50 mg theacrine) were administered together with 240 mL non‑carbonated water.","source":"caffeine-saliva-half-life"},"caffeine-saliva-half-life/crossover_design":{"id":"caffeine-saliva-half-life/crossover_design","kind":"context","label":"Crossover study design with four arms","quote":"The in vivo study was performed in a cross over design with four different study arms involving twelve young volunteers aged 22–35 years (2 females and 10 males).","source":"caffeine-saliva-half-life"},"caffeine-saliva-half-life/half_life_caffeine":{"id":"caffeine-saliva-half-life/half_life_caffeine","kind":"estimate","label":"Caffeine half-life in saliva after a single 25 mg dose (arm A), mean ± SD, n = 12","quote":"Caffeine showed a half-life of 5.15 ± 1.21 h after single administration, whereas the half-life of methylliberine was only 1.15 ± 0.12 h and that of theacrine 21.00 ± 7.55 h.","source":"caffeine-saliva-half-life","why":"People were assigned at random, but only 12 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Elimination half-life of caffeine in saliva after 25 mg taken alone (arm A)","measure":"mean","point":5.15,"ciLow":null,"ciHigh":null,"unit":"h","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":1.21}},"caffeine-saliva-half-life/matrix_saliva":{"id":"caffeine-saliva-half-life/matrix_saliva","kind":"context","label":"What was measured: caffeine in saliva samples collected by the participants over 24 h","quote":"Post-administration, subjects collected saliva samples at fixed times (4, 8, 12, 16, 20, 25, 30, 35, 40, 50, 60, 90, 120, 180, 240, 360, 480, 600 and 1440 min) over 24 h.","source":"caffeine-saliva-half-life"},"capsules":{"id":"capsules","kind":"context","label":"Treatment delivery","quote":"participants took either caffeine (150 mg) or placebo (mannitol) in identical appearing gelatin capsules (Hänseler AG, Herisau, Switzerland)"},"daily_reverse":{"id":"daily_reverse","kind":"statement","label":"Habitual consumers may reverse overnight withdrawal with the first dose each day","quote":"This reduction might reflect withdrawal symptoms which chronic consumers reverse daily by the first caffeine dose."},"dose":{"id":"dose","kind":"context","label":"The three conditions and the dose","quote":"caffeine (3 × 150 mg caffeine daily), withdrawal (3 × 150 mg caffeine for 8 days, then switch to placebo), and placebo (3 × placebo daily)"},"evening":{"id":"evening","kind":"context","label":"What earlier work reports for caffeine taken in the evening","quote":"caffeine consumed in the evening hours prolongs sleep latency, reduces total sleep time (TST), shortens deep sleep"},"good_sleepers":{"id":"good_sleepers","kind":"context","label":"Participants were good sleepers","quote":"all volunteers reported good sleep quality assessed with the Pittsburgh Sleep Quality Index (PSQI; score ≤ 5)"},"later_bed":{"id":"later_bed","kind":"statement","label":"Bedtime at home was later on caffeine","quote":"the ambulatory sleep episodes were on average around 25 min later as compared to placebo"},"lim_male":{"id":"lim_male","kind":"limitation","label":"Men only","quote":"only male volunteers were included which clearly reduces the generalizability of the findings"},"lim_n":{"id":"lim_n","kind":"limitation","label":"Small sample","quote":"Second, only a limited number of participants were studied."},"lim_young":{"id":"lim_young","kind":"limitation","label":"Only young adults","quote":"Thus, the present results cannot be generalized to other age groups such as to middle-aged consumers which are more vulnerable to the caffeine-induced effects on sleep."},"no_depth_change":{"id":"no_depth_change","kind":"statement","label":"The predicted loss of deep sleep was not found","quote":"Taken together, we could not confirm our assumption of a caffeine-induced reduction of sleep depth, neither in terms of shorter SWS nor in terms of reduced SWA in the caffeine compared to the placebo condition."},"not_after_abstinence":{"id":"not_after_abstinence","kind":"statement","label":"The result may not hold after several days without caffeine","quote":"Importantly, our findings do not preclude potential impairments of nighttime sleep after morning caffeine intake, if preceded by several days of abstinence from the stimulant."},"quality_same":{"id":"quality_same","kind":"finding","label":"no clear difference between conditions","quote":"Analyses of subjective sleep quality assessed with the Leeds Sleep Evaluation Questionnaire (LSEQ) did not reveal significant differences among the three conditions in any of the four domains of sleep quality (> 0.05)","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated sleep quality","tier":"low"}},"recording":{"id":"recording","kind":"context","label":"When sleep was recorded relative to the last caffeine dose","quote":"After 9 days of continuous treatment, electroencephalographically (EEG)-derived sleep structure and intensity were recorded during a scheduled 8-h nighttime sleep episode starting 8 (caffeine condition) and 15 h (withdrawal condition) after the last caffeine intake."},"sample":{"id":"sample","kind":"context","label":"Number and sex of participants","quote":"Twenty male volunteers were recruited into the present study through online advertisements and flyers distributed in public areas."},"schedule":{"id":"schedule","kind":"context","label":"When the capsules were taken","quote":"three times daily, scheduled at 45 min, 255 min, and 475 min after awakening, for a duration of 10 days"},"sigma":{"id":"sigma","kind":"finding","label":"lower than placebo in both the caffeine and withdrawal conditions, a clear difference","quote":"power density was significantly reduced compared to placebo in the sigma range during both withdrawal","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Sigma-band brain activity during non-REM sleep","tier":"low"}},"sigma_meaning":{"id":"sigma_meaning","kind":"statement","label":"Authors'' interpretation of the sigma change","quote":"These subtle alterations point to early signs of caffeine withdrawal in the homeostatic aspect of sleep-wake regulation which are already present as early as 8 h after the last caffeine intake."},"sleep_same":{"id":"sleep_same","kind":"finding","label":"no clear difference from placebo; the paper does not say how big any difference was","quote":"the analyses of the polysomnography (PSG) did not reveal significant differences in total sleep time (TST), sleep efficiency (SE), sleep latencies, or the relative amount of sleep stages among the three conditions (> 0.05)","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total sleep time, time to fall asleep and sleep stages","tier":"low"}},"tolerance":{"id":"tolerance","kind":"context","label":"Earlier work on tolerance, cited by the authors","quote":"Accordingly, a 1-week treatment of caffeine reduced the sleep disrupting effects, even under conditions of high evening dosages."},"who":{"id":"who","kind":"context","label":"Age range and habitual caffeine intake","quote":"Interested individuals aged between 18 and 35 years old (mean age ± SD: 26.4 ± 4 years) and reporting a daily caffeine consumption between 300 and 600 mg (mean intake ± SD: 478.1 ± 102.8 mg) were included."}},"context":{"studies":[{"slug":"caffeine-saliva-half-life","citation":"Wildgrube T, Senekowitsch S, Krüger R, Winter F, Grimm M, Weitschies W, Schick P. A comparison of theacrine and methylliberine with caffeine as salivary markers for determining gastric emptying. Int J Pharm X. 2025;10:100442.","shortCite":"Wildgrube et al., International journal of pharmaceutics: X 2025","doi":"10.1016/j.ijpx.2025.100442","design":"crossover","sampleSize":12,"license":"CC-BY","tier":"low","why":"People were assigned at random, but only 12 took part, so a bigger trial could change the picture."}],"concepts":[{"slug":"adenosine","term":"adenosine","plain":"A tiredness signal made in the brain. It builds up the longer you stay awake, as brain cells burn energy. When it settles onto brain cells it slows them down, and you feel sleepy. Sleep clears it away.","model":"Tokens that pile up through the waking day and park on brain cells. The more that park, the sleepier you feel. A night''s sleep sweeps the car park clear.","reference":{"doi":"10.1126/science.276.5316.1265","title":"Adenosine: a mediator of the sleep-inducing effects of prolonged wakefulness"}}]}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('2f0cc739-d18b-5ca3-9981-5971623614e9', 'key_takeaways', '{"takeaways":[[{"text":"The schedule tested was three doses, the last one 475 minutes after waking, which came 8 hours before bed.","refs":["schedule","recording"]}],[{"text":"The finding covers a steady daily habit.","refs":["who"]},{"text":"The authors caution that it may not hold after several days without caffeine.","refs":["not_after_abstinence"]}],[{"text":"Bedtime at home drifted about 25 minutes later on caffeine, so watch the clock as well as the cup.","refs":["later_bed"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('4c89568a-c91b-58ce-b9af-7a0f80d6331c', '2f0cc739-d18b-5ca3-9981-5971623614e9', 1, 'Last caffeine at least 8 hours before bed', 'The gap this trial tested. It did not test anything shorter.', 'action', 'low', 'Total sleep time, time to fall asleep and sleep stages: no clear difference from placebo; the paper does not say how big any difference was', null, null, null, null, null, null),
  ('2a1328ac-dcb7-5ff1-9f9a-489cc00ee384', '2f0cc739-d18b-5ca3-9981-5971623614e9', 2, 'In bed within 30 minutes of my usual time', 'Participants were asked to keep to this at home. The trial did not test it, so it carries no weight.', 'action', 'none', null, null, null, null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- hiit-body-composition
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', 'hiit-body-composition', 'Interval training''s best-supported effect is on lean mass, not fat: thirty-six trials, graded', '10.3390/jcm12062291', 'Body composition', 'Across thirty-six randomized trials in adults, interval training reduced body fat percentage by 1.53 points. In the same adults, it raised fat-free mass by 0.51 kg. The fat result is graded low certainty. The lean-mass result is graded high, and it hangs on a single trial.', 'premium', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', '{"hook":[{"text":"Interval training is sold on fat loss.","refs":[]},{"text":"Pool the trials, rate how far each result can be trusted, and the order flips.","refs":["grade_ffm","grade_bf"]}],"populationPanel":[{"text":"Who was studied: 1,130 adults with a mean age of 26.27 years, across thirty-six randomized trials lasting 3 to 15 weeks.","refs":["sample","trials"]},{"text":"Most were inactive and overweight or obese, so the findings describe that group best.","refs":["lim_population"]},{"text":"Children, teenagers and people with a known disease were left out.","refs":["excluded"]}],"sections":[],"limitations":[],"layers":{"mechanism":{"paragraphs":[[{"text":"Picture your weight as two piles on one scale.","refs":["concept:fat-free-mass"]},{"text":"One pile is fat; the other is everything else: muscle, bone, organs, blood and water.","refs":["concept:fat-free-mass"]},{"text":"A bathroom scale reads only the two together.","refs":["concept:fat-free-mass"]},{"text":"The second pile has a name: fat-free mass.","refs":["ffm_all"]}],[{"text":"Interval training means bursts of hard work with rests between them.","refs":["recipe"]}],[{"text":"In these trials, interval training moved the two piles in opposite directions.","refs":["fm_all","ffm_all"]},{"text":"Compared with no exercise, the fat pile shrank by 1.86 kg on average, and the other pile grew by 0.51 kg.","refs":["fm_all","ffm_all"]}],[{"text":"So a bathroom scale would show less than what changed underneath.","refs":["fm_all","ffm_all"]}]],"figure":{"figure":"two-piles","headline":[{"text":"The scale weighs two things.","refs":[]},{"text":"In these trials, interval training moved them in opposite directions.","refs":["fm_all","ffm_all"]}],"caption":[{"text":"Dotted: a sketch of the idea, not data.","refs":[]},{"text":"Orange words: what the pooled trials measured.","refs":["fm_all","ffm_all"]},{"text":"Dashed: the pattern the authors found more effective.","refs":["recipe"]}],"alt":"Two panels, before and after 3 to 15 weeks of training, each with a standing outline beside two stacked blocks: fat below, everything else above. After training, the fat block is marked less, on average, and the other block a little more, on average. The blocks are drawn the same size in both panels, because the paper gives no sizes. Below, two strips show two ways to build a session: short hard bursts with short easy rests, and long bursts with long still rests. The authors found the first pattern more effective.","params":{"title":"Fat and fat-free mass, before and after interval training","body":{"sketch":"two-piles","concept":"fat-free-mass","tag":"Sketch, not data","ink":"ink","labels":{"fat":"Fat","free":"Fat-free mass: everything else (muscle, bone, water)"},"alt":"Two stacked blocks beside a standing outline: a sketch of the body as a fat pile and a pile of everything else. The blocks are the same size in both panels; their sizes are not data."},"before":"Before","after":{"lead":"After","span":{"text":"3 to 15 weeks","ref":"trials"}},"fat":{"change":"Less, on average","kind":"measured","fact":{"id":"fm_all","kind":"estimate","label":"Fat mass, all interval training vs control","quote":"HIIT resulted in a significant reduction in FM (WMD: −1.86 kg, 95% CI: −2.55 to −1.18","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.86,"ciLow":-2.55,"ciHigh":-1.18,"unit":"kg","absolute":true,"tier":"moderate"}}},"free":{"change":"A little more, on average","kind":"measured","fact":{"id":"ffm_all","kind":"estimate","label":"Fat-free mass, all interval training vs control","quote":"HIIT induced an overall significant improvement in FFM (WMD: 0.51 kg, 95% CI: 0.06 to 0.95","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.51,"ciLow":0.06,"ciHigh":0.95,"unit":"kg","absolute":true,"tier":"high"}}},"why":"The trials did not test why.","short":{"title":"Short bursts, short active rests","kind":"measured","fact":{"id":"ffm_le60","kind":"estimate","label":"Fat-free mass, work bursts of 60 s or less","quote":"≤60 s produced a significant increase in FFM (WMD: 0.57 kg, 95% CI: 0.29 to 1.44","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.57,"ciLow":0.29,"ciHigh":1.44,"unit":"kg","absolute":true,"tier":"high"}},"burst":{"lead":"Hard effort,","n":{"n":60,"ref":"ffm_le60"},"unit":"seconds or less"},"rest":{"lead":"Easy movement,","n":{"n":90,"ref":"ffm_rest_le90"},"unit":"seconds or less"}},"long":{"title":"Long bursts, long still rests"},"recipe":{"words":"The authors found the first pattern more effective.","kind":"proposed","fact":{"id":"recipe","kind":"statement","label":"The programme settings the authors found more effective","quote":"These data suggest that training for more than 8 weeks, at least three sessions per week, lower than 60 s work intervals separated by ≤90 s recovery periods, and active rest (instead of passive) are more effective on body composition."}}}}},"protocol":{"paragraphs":[[{"text":"The trials compared interval training with no exercise, for 3 to 15 weeks.","refs":["trials"]},{"text":"Then the authors rated how far they could trust each result.","refs":["grade_ffm"]},{"text":"Fat-free mass rated high, fat mass moderate and body fat percentage low.","refs":["grade_ffm","grade_fm","grade_bf"]}],[{"text":"Some settings kept coming out ahead.","refs":["recipe"]},{"text":"More than 8 weeks, three sessions a week, bursts under 60 seconds, and rests of 90 seconds or less, spent moving.","refs":["recipe"]},{"text":"These leads come from comparing groups of trials, not from testing one setting against another.","refs":["subgroups"]}],[{"text":"For fat-free mass, only cycling showed a clear gain; running did not.","refs":["ffm_cycling","ffm_only_cycling"]}]],"figure":{"figure":"order-flips","headline":[{"text":"Sold on fat loss.","refs":[]},{"text":"The surest result is that fat-free mass held up.","refs":["ffm_all","grade_ffm"]}],"caption":[{"text":"Compared with people who did no training.","refs":["ffm_all","fm_all","bf_all"]},{"text":"Mostly inactive adults carrying extra weight.","refs":["lim_population"]}],"alt":"Three rows, surest evidence first. Fat-free mass: 0.51 kg more, strong evidence. Fat: 1.86 kg less, decent evidence. Body fat share: 1.53 points less, early evidence. With one trial left out, the fat-free-mass range crosses no change.","params":{"title":"What thirty-six trials found, surest first","pitchTitle":"How it''s sold","after":{"text":"3 to 15 weeks","ref":"trials"},"rows":[{"outcome":"ffm","label":"Fat-free mass","pitch":"lean mass","kind":"measured","fact":{"id":"ffm_all","kind":"estimate","label":"Fat-free mass, all interval training vs control","quote":"HIIT induced an overall significant improvement in FFM (WMD: 0.51 kg, 95% CI: 0.06 to 0.95","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.51,"ciLow":0.06,"ciHigh":0.95,"unit":"kg","absolute":true,"tier":"high"}}},{"outcome":"fm","label":"Fat","pitch":"fat loss","kind":"measured","fact":{"id":"fm_all","kind":"estimate","label":"Fat mass, all interval training vs control","quote":"HIIT resulted in a significant reduction in FM (WMD: −1.86 kg, 95% CI: −2.55 to −1.18","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.86,"ciLow":-2.55,"ciHigh":-1.18,"unit":"kg","absolute":true,"tier":"moderate"}}},{"outcome":"bf","label":"Body fat share","pitch":"body fat share","kind":"measured","fact":{"id":"bf_all","kind":"estimate","label":"Body fat percentage, all interval training vs control","quote":"induced a significant reduction in BF% [weighted mean difference (WMD): −1.53%, 95% CI: −2.13, −0.92","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.53,"ciLow":-2.13,"ciHigh":-0.92,"unit":"points","absolute":true,"tier":"low"}}}],"pitch":["fm","bf","ffm"],"sensitivity":{"outcome":"ffm","lead":"With one trial left out","crosses":"and the range crosses no change."}}},"figureSlot":"try"},"audit":{"effect":[{"text":"Fat-free mass: 0.51 kg more than with no exercise, pooled across the trials.","refs":["ffm_all"]},{"text":"Fat mass: 1.86 kg less.","refs":["fm_all"]},{"text":"Body fat percentage: 1.53 points less.","refs":["bf_all"]}],"weakEnd":[{"text":"The 95% confidence interval for fat-free mass runs from 0.06 kg to 0.95 kg.","refs":["ffm_all"]},{"text":"At its weak end, 0.06 kg is an amount no bathroom scale would register.","refs":["ffm_all"]},{"text":"High certainty means the trials agree that the average is above zero, not that it is big.","refs":["grade_ffm","ffm_no_het"]}],"limitations":[[{"text":"Most trials enrolled inactive adults who were overweight or obese.","refs":["lim_population"]},{"text":"People who already train may respond differently.","refs":["lim_population"]}],[{"text":"The trials disagreed with one another, most of all on body fat percentage, which is why the authors graded it low.","refs":["lim_heterogeneity","grade_bf"]}],[{"text":"The trials measured body composition in different ways, from skinfold calipers to DEXA scans.","refs":["lim_methods"]}],[{"text":"Take one trial out and the fat-free-mass result is no longer clear.","refs":["lim_loo"]}]],"missed":[{"text":"Leave that trial out and the estimate becomes 0.46 kg lost, ranging from 1.38 kg lost to 0.44 kg gained.","refs":["ffm_loo"]},{"text":"So the best-graded result also rests on a single study.","refs":["ffm_loo","grade_ffm"]}],"more":[[{"text":"Cycling’s fat-free-mass gain was 0.63 kg (95% CI 0.17 to 1.09).","refs":["ffm_cycling"]}],[{"text":"Overground running showed the widest drop in body fat percentage, 2.80 points (95% CI 3.89 to 1.71), on the outcome graded low.","refs":["bf_overground","grade_bf"]}],[{"text":"Treadmill running showed no clear difference in fat mass: from 2.82 kg lost to 0.62 kg gained.","refs":["fm_treadmill"]}],[{"text":"An earlier pooled analysis found no clear effect of cycling on fat mass in overweight and obese adults.","refs":["wewege"]}],[{"text":"Heavier bodies load the joints differently when running, one reason cycling may suit some people.","refs":["joints"]}]],"figure":null}},"glossary":[{"term":"fat-free mass","plain":"Everything in your body that is not fat: muscle, bone, organs, blood and the water in and around your cells. A body scan can split your weight into fat and this rest; an ordinary bathroom scale cannot.","refs":[],"concept":"fat-free-mass"},{"term":"interval training","plain":"Exercise in bursts of hard work, with rests between them.","refs":["recipe"],"concept":null},{"term":"randomized","plain":"Chance decided who did the training and who did not, not the researchers.","refs":["trials"],"concept":null}],"primaryEstimate":"ffm_all","finding":{"question":[{"text":"Does interval training change your body fat and lean mass?","refs":["trials"]}],"headline":[{"text":"Fat-free mass +0.51 kg;","refs":["ffm_all"]},{"text":"fat mass −1.86 kg;","refs":["fm_all"]},{"text":"both vs no exercise, trials pooled.","refs":["trials"]}],"support":[{"text":"Fat-free mass is everything in the body that is not fat.","refs":["ffm_all"]}]},"simulator":{"kind":"hiit-forest","params":{"outcomes":[{"id":"ffm","label":"Fat-free mass","better":"up","grade":{"id":"grade_ffm","kind":"grade","label":"GRADE certainty for fat-free mass","quote":"which indicated the effect of FFM to be of high quality"},"overall":{"id":"ffm_all","kind":"estimate","label":"Fat-free mass, all interval training vs control","quote":"HIIT induced an overall significant improvement in FFM (WMD: 0.51 kg, 95% CI: 0.06 to 0.95","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.51,"ciLow":0.06,"ciHigh":0.95,"unit":"kg","absolute":true,"tier":"high"}}},{"id":"fm","label":"Fat mass","better":"down","grade":{"id":"grade_fm","kind":"grade","label":"GRADE certainty for fat mass","quote":"the evidence about FM and BF% was downgraded to medium and low levels, respectively"},"overall":{"id":"fm_all","kind":"estimate","label":"Fat mass, all interval training vs control","quote":"HIIT resulted in a significant reduction in FM (WMD: −1.86 kg, 95% CI: −2.55 to −1.18","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.86,"ciLow":-2.55,"ciHigh":-1.18,"unit":"kg","absolute":true,"tier":"moderate"}}},{"id":"bf","label":"Body fat percentage","better":"down","grade":{"id":"grade_bf","kind":"grade","label":"GRADE certainty for body fat percentage","quote":"the evidence about FM and BF% was downgraded to medium and low levels, respectively"},"overall":{"id":"bf_all","kind":"estimate","label":"Body fat percentage, all interval training vs control","quote":"induced a significant reduction in BF% [weighted mean difference (WMD): −1.53%, 95% CI: −2.13, −0.92","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.53,"ciLow":-2.13,"ciHigh":-0.92,"unit":"points","absolute":true,"tier":"low"}}}],"settings":[{"id":"modality","label":"Type of interval","options":[{"id":"cycling","label":"Cycling","ffm":{"id":"ffm_cycling","kind":"estimate","label":"Fat-free mass, cycling","quote":"only HIIT involving cycling interventions resulted in a significant increase in FFM compared to other exercise modalities (WMD: 0.63 kg, 95% CI: 0.17 to 1.09","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.63,"ciLow":0.17,"ciHigh":1.09,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_cycling","kind":"estimate","label":"Fat mass, cycling","quote":"cycling and overground running reduced FM (WMD: −1.72 kg, 95% CI: −2.41 to −1.30,0.001 and WMD: −4.25 kg, 95% CI: −5.90 to −2.61","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.72,"ciLow":-2.41,"ciHigh":-1.3,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":null,"subgroup":"cycling"},{"id":"overground","label":"Overground running","ffm":null,"fm":{"id":"fm_overground","kind":"estimate","label":"Fat mass, overground running","quote":"cycling and overground running reduced FM (WMD: −1.72 kg, 95% CI: −2.41 to −1.30,0.001 and WMD: −4.25 kg, 95% CI: −5.90 to −2.61","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-4.25,"ciLow":-5.9,"ciHigh":-2.61,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_overground","kind":"estimate","label":"Body fat percentage, overground running","quote":"overground running induced the largest overall effect (WMD: −2.80%, 95% CI: −3.89 to −1.71","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-2.8,"ciLow":-3.89,"ciHigh":-1.71,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"overground running"},{"id":"treadmill","label":"Treadmill running","ffm":null,"fm":{"id":"fm_treadmill","kind":"estimate","label":"Fat mass, treadmill running","quote":"treadmill running did not induce significant changes (WMD: −1.10 kg, 95% CI: −2.82 to 0.62","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.1,"ciLow":-2.82,"ciHigh":0.62,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":null,"subgroup":"treadmill running"}]},{"id":"weeks","label":"Programme length","options":[{"id":"over8","label":"More than 8 weeks","ffm":{"id":"ffm_over8","kind":"estimate","label":"Fat-free mass, programmes longer than 8 weeks","quote":"produced larger effects than trials of shorter (i.e., less than 8 weeks) durations (WMD: 0.63 kg, 95% CI: 0.17 to 1.10","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.63,"ciLow":0.17,"ciHigh":1.1,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_over8","kind":"estimate","label":"Fat mass, programmes longer than 8 weeks","quote":"a larger effect on FM was noted when compared to shorter (i.e., less than 8 weeks) interventions (WMD: −1.92 kg, 95% CI: −2.35 to −1.50","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.92,"ciLow":-2.35,"ciHigh":-1.5,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_over8","kind":"estimate","label":"Body fat percentage, programmes longer than 8 weeks","quote":"a larger effect on BF% was noted when compared to shorter (i.e., less than 8 weeks) interventions (WMD: −2.08%, 95% CI: −2.40 to −1.76","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-2.08,"ciLow":-2.4,"ciHigh":-1.76,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"longer than 8 weeks"},{"id":"upto8","label":"8 weeks or less","ffm":null,"fm":null,"bf":null,"subgroup":"8 weeks or less"}]},{"id":"frequency","label":"Sessions a week","options":[{"id":"three","label":"Three","ffm":{"id":"ffm_3wk","kind":"estimate","label":"Fat-free mass, 3 sessions a week","quote":"3 sessions per week induced a significant increase in FFM (WMD: 0.50 kg, 95% CI: 0.06 to 0.94","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.5,"ciLow":0.06,"ciHigh":0.94,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_3wk","kind":"estimate","label":"Fat mass, 3 sessions a week","quote":"2 and 3 sessions per week had a significant effect on reducing FM (WMD: −4.43 kg, 95% CI: −6.62 to −2.24,0.001 and WMD: −1.24 kg, 95% CI: −2.00 to −0.48","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.24,"ciLow":-2,"ciHigh":-0.48,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_3wk","kind":"estimate","label":"Body fat percentage, 3 sessions a week","quote":"three sessions per week had a significant effect on reducing BF% (WMD: −1.17%, 95% CI: −1.85 to −0.50,0.001), while two sessions per week were not significant (WMD: −3.23%, 95% CI: −6.52 to 0.04","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.17,"ciLow":-1.85,"ciHigh":-0.5,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"3 sessions a week"},{"id":"two","label":"Two","ffm":null,"fm":{"id":"fm_2wk","kind":"estimate","label":"Fat mass, 2 sessions a week","quote":"2 and 3 sessions per week had a significant effect on reducing FM (WMD: −4.43 kg, 95% CI: −6.62 to −2.24,0.001 and WMD: −1.24 kg, 95% CI: −2.00 to −0.48","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-4.43,"ciLow":-6.62,"ciHigh":-2.24,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_2wk","kind":"estimate","label":"Body fat percentage, 2 sessions a week","quote":"three sessions per week had a significant effect on reducing BF% (WMD: −1.17%, 95% CI: −1.85 to −0.50,0.001), while two sessions per week were not significant (WMD: −3.23%, 95% CI: −6.52 to 0.04","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-3.23,"ciLow":-6.52,"ciHigh":0.04,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"2 sessions a week"}]},{"id":"work","label":"Each work burst","options":[{"id":"short","label":"60 seconds or less","ffm":{"id":"ffm_le60","kind":"estimate","label":"Fat-free mass, work bursts of 60 s or less","quote":"≤60 s produced a significant increase in FFM (WMD: 0.57 kg, 95% CI: 0.29 to 1.44","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.57,"ciLow":0.29,"ciHigh":1.44,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_le60","kind":"estimate","label":"Fat mass, work bursts of 60 s or less","quote":"produced a significant reduction in FM (WMD: −2.20 kg, 95% CI: −3.01 to −1.39,0.001 and WMD: −1.14 kg, 95% CI: −2.13 to −0.15","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-2.2,"ciLow":-3.01,"ciHigh":-1.39,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_le60","kind":"estimate","label":"Body fat percentage, work bursts of 60 s or less","quote":"produced a significant reduction in BF% (WMD: −1.87%, 95% CI: −2.78 to −0.96,0.001 and WMD: −0.92%, 95% CI: −1.71 to −0.13","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.87,"ciLow":-2.78,"ciHigh":-0.96,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"bursts of 60 seconds or less"},{"id":"long","label":"More than 60 seconds","ffm":{"id":"ffm_gt60","kind":"estimate","label":"Fat-free mass, work bursts longer than 60 s","quote":">60 s did not induce significant changes (WMD: −0.85 kg, 95% CI: −2.28 to 0.57","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":-0.85,"ciLow":-2.28,"ciHigh":0.57,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_gt60","kind":"estimate","label":"Fat mass, work bursts longer than 60 s","quote":"produced a significant reduction in FM (WMD: −2.20 kg, 95% CI: −3.01 to −1.39,0.001 and WMD: −1.14 kg, 95% CI: −2.13 to −0.15","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.14,"ciLow":-2.13,"ciHigh":-0.15,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_gt60","kind":"estimate","label":"Body fat percentage, work bursts longer than 60 s","quote":"produced a significant reduction in BF% (WMD: −1.87%, 95% CI: −2.78 to −0.96,0.001 and WMD: −0.92%, 95% CI: −1.71 to −0.13","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-0.92,"ciLow":-1.71,"ciHigh":-0.13,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"bursts longer than 60 seconds"}]},{"id":"rest","label":"Rest between bursts","options":[{"id":"short","label":"90 seconds or less","ffm":{"id":"ffm_rest_le90","kind":"estimate","label":"Fat-free mass, rests of 90 s or less","quote":"The rest time subgroup for ≤90 s and active rest showed a significant increase in FFM (WMD: 0.70 kg, 95% CI: 0.22 to 1.18,0.004 and WMD: 0.68 kg, 95% CI: 0.20 to 1.17","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.7,"ciLow":0.22,"ciHigh":1.18,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_rest_le90","kind":"estimate","label":"Fat mass, rests of 90 s or less","quote":"showed a significant reduction in FM (WMD: −2.26 kg, 95% CI: −3.08 to −1.43,0.001 and WMD: −1.07 kg, 95% CI: −1.99 to −0.15","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-2.26,"ciLow":-3.08,"ciHigh":-1.43,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_rest_le90","kind":"estimate","label":"Body fat percentage, rests of 90 s or less","quote":"showed a significant reduction in BF% (WMD: −1.94%, 95% CI: −2.83 to −1.06,0.001 and WMD: −1.01%, 95% CI: −1.84 to −0.10","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.94,"ciLow":-2.83,"ciHigh":-1.06,"unit":"points","absolute":true,"tier":"low"}},"subgroup":"rests of 90 seconds or less"},{"id":"long","label":"More than 90 seconds","ffm":{"id":"ffm_rest_gt90","kind":"estimate","label":"Fat-free mass, rests longer than 90 s","quote":"passive and >90 s rest had no significant increase on FFM (WMD: −0.26 kg, 95% CI: −1.44 to 0.91,0.657, and WMD:−0.53 kg, 95% CI: −1.81 to 0.73","why":"The authors rated how sure th