stimate","label":"Fat mass, all interval training vs control","quote":"HIIT resulted in a significant reduction in FM (WMD: −1.86 kg, 95% CI: −2.55 to −1.18","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.86,"ciLow":-2.55,"ciHigh":-1.18,"unit":"kg","absolute":true,"tier":"moderate"}}},{"outcome":"bf","label":"Body fat share","pitch":"body fat share","kind":"measured","fact":{"id":"bf_all","kind":"estimate","label":"Body fat percentage, all interval training vs control","quote":"induced a significant reduction in BF% [weighted mean difference (WMD): −1.53%, 95% CI: −2.13, −0.92","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.53,"ciLow":-2.13,"ciHigh":-0.92,"unit":"points","absolute":true,"tier":"low"}}}],"pitch":["fm","bf","ffm"],"sensitivity":{"outcome":"ffm","lead":"With one trial left out","crosses":"and the range crosses no change."}}},"x":[{"text":"Change compared with no exercise","refs":[]}],"y":[],"alt":[{"text":"Three rows, surest evidence first: fat-free mass, fat, then body fat share. Beside them, the order it is usually sold in, fat loss first. Each row has its own scale and a line for no change.","refs":["ffm_all","fm_all","bf_all","grade_ffm","grade_fm","grade_bf"]}],"note":[{"text":"Ranges from the pooled trials. Members can try it with their own training inside.","refs":[]}],"tryIt":[{"text":"pick your training","refs":[]}]},"sourceLine":"1,130 adults · pooled randomized trials · 3 to 15 weeks each","facts":{"bf_2wk":{"id":"bf_2wk","kind":"estimate","label":"Body fat percentage, 2 sessions a week","quote":"three sessions per week had a significant effect on reducing BF% (WMD: −1.17%, 95% CI: −1.85 to −0.50,0.001), while two sessions per week were not significant (WMD: −3.23%, 95% CI: −6.52 to 0.04","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-3.23,"ciLow":-6.52,"ciHigh":0.04,"unit":"points","absolute":true,"tier":"low"}},"bf_3wk":{"id":"bf_3wk","kind":"estimate","label":"Body fat percentage, 3 sessions a week","quote":"three sessions per week had a significant effect on reducing BF% (WMD: −1.17%, 95% CI: −1.85 to −0.50,0.001), while two sessions per week were not significant (WMD: −3.23%, 95% CI: −6.52 to 0.04","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.17,"ciLow":-1.85,"ciHigh":-0.5,"unit":"points","absolute":true,"tier":"low"}},"bf_all":{"id":"bf_all","kind":"estimate","label":"Body fat percentage, all interval training vs control","quote":"induced a significant reduction in BF% [weighted mean difference (WMD): −1.53%, 95% CI: −2.13, −0.92","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.53,"ciLow":-2.13,"ciHigh":-0.92,"unit":"points","absolute":true,"tier":"low"}},"bf_overground":{"id":"bf_overground","kind":"estimate","label":"Body fat percentage, overground running","quote":"overground running induced the largest overall effect (WMD: −2.80%, 95% CI: −3.89 to −1.71","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it low.","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-2.8,"ciLow":-3.89,"ciHigh":-1.71,"unit":"points","absolute":true,"tier":"low"}},"excluded":{"id":"excluded","kind":"context","label":"Who was excluded","quote":"performed in children and teenagers (years < 18), were review and/or observational in nature, lacked a control group, or involved population cohorts with a known disease were excluded from the meta-analysis"},"ffm_3wk":{"id":"ffm_3wk","kind":"estimate","label":"Fat-free mass, 3 sessions a week","quote":"3 sessions per week induced a significant increase in FFM (WMD: 0.50 kg, 95% CI: 0.06 to 0.94","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.5,"ciLow":0.06,"ciHigh":0.94,"unit":"kg","absolute":true,"tier":"high"}},"ffm_active":{"id":"ffm_active","kind":"estimate","label":"Fat-free mass, active rest","quote":"The rest time subgroup for ≤90 s and active rest showed a significant increase in FFM (WMD: 0.70 kg, 95% CI: 0.22 to 1.18,0.004 and WMD: 0.68 kg, 95% CI: 0.20 to 1.17","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.68,"ciLow":0.2,"ciHigh":1.17,"unit":"kg","absolute":true,"tier":"high"}},"ffm_all":{"id":"ffm_all","kind":"estimate","label":"Fat-free mass, all interval training vs control","quote":"HIIT induced an overall significant improvement in FFM (WMD: 0.51 kg, 95% CI: 0.06 to 0.95","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.51,"ciLow":0.06,"ciHigh":0.95,"unit":"kg","absolute":true,"tier":"high"}},"ffm_cycling":{"id":"ffm_cycling","kind":"estimate","label":"Fat-free mass, cycling","quote":"only HIIT involving cycling interventions resulted in a significant increase in FFM compared to other exercise modalities (WMD: 0.63 kg, 95% CI: 0.17 to 1.09","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.63,"ciLow":0.17,"ciHigh":1.09,"unit":"kg","absolute":true,"tier":"high"}},"ffm_gt60":{"id":"ffm_gt60","kind":"estimate","label":"Fat-free mass, work bursts longer than 60 s","quote":">60 s did not induce significant changes (WMD: −0.85 kg, 95% CI: −2.28 to 0.57","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":-0.85,"ciLow":-2.28,"ciHigh":0.57,"unit":"kg","absolute":true,"tier":"high"}},"ffm_le60":{"id":"ffm_le60","kind":"estimate","label":"Fat-free mass, work bursts of 60 s or less","quote":"≤60 s produced a significant increase in FFM (WMD: 0.57 kg, 95% CI: 0.29 to 1.44","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.57,"ciLow":0.29,"ciHigh":1.44,"unit":"kg","absolute":true,"tier":"high"}},"ffm_loo":{"id":"ffm_loo","kind":"estimate","label":"Fat-free mass after removing one trial (sensitivity analysis)","quote":"the removal of one study [] in particular eliminated any observed significant overall effect of HIIT on FFM (WMD: −0.46, 95% CI: −1.38 to 0.44)","why":"It pools trials that assigned people at random, which rules out most other explanations.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":-0.46,"ciLow":-1.38,"ciHigh":0.44,"unit":"kg","absolute":true,"tier":"moderate"}},"ffm_no_het":{"id":"ffm_no_het","kind":"statement","label":"The fat-free-mass trials agreed with each other","quote":"which was further emphasized by no heterogeneity among studies"},"ffm_only_cycling":{"id":"ffm_only_cycling","kind":"statement","label":"Running did not increase fat-free mass","quote":"while treadmill running and overground running did not increase FFM"},"ffm_over8":{"id":"ffm_over8","kind":"estimate","label":"Fat-free mass, programmes longer than 8 weeks","quote":"produced larger effects than trials of shorter (i.e., less than 8 weeks) durations (WMD: 0.63 kg, 95% CI: 0.17 to 1.10","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.63,"ciLow":0.17,"ciHigh":1.1,"unit":"kg","absolute":true,"tier":"high"}},"ffm_passive":{"id":"ffm_passive","kind":"estimate","label":"Fat-free mass, passive rest","quote":"passive and >90 s rest had no significant increase on FFM (WMD: −0.26 kg, 95% CI: −1.44 to 0.91,0.657, and WMD:−0.53 kg, 95% CI: −1.81 to 0.73","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":-0.26,"ciLow":-1.44,"ciHigh":0.91,"unit":"kg","absolute":true,"tier":"high"}},"ffm_rest_le90":{"id":"ffm_rest_le90","kind":"estimate","label":"Fat-free mass, rests of 90 s or less","quote":"The rest time subgroup for ≤90 s and active rest showed a significant increase in FFM (WMD: 0.70 kg, 95% CI: 0.22 to 1.18,0.004 and WMD: 0.68 kg, 95% CI: 0.20 to 1.17","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it high.","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.7,"ciLow":0.22,"ciHigh":1.18,"unit":"kg","absolute":true,"tier":"high"}},"fm_all":{"id":"fm_all","kind":"estimate","label":"Fat mass, all interval training vs control","quote":"HIIT resulted in a significant reduction in FM (WMD: −1.86 kg, 95% CI: −2.55 to −1.18","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.86,"ciLow":-2.55,"ciHigh":-1.18,"unit":"kg","absolute":true,"tier":"moderate"}},"fm_treadmill":{"id":"fm_treadmill","kind":"estimate","label":"Fat mass, treadmill running","quote":"treadmill running did not induce significant changes (WMD: −1.10 kg, 95% CI: −2.82 to 0.62","why":"The authors rated how sure they are of this pooled result with a standard checklist, and rated it moderate.","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.1,"ciLow":-2.82,"ciHigh":0.62,"unit":"kg","absolute":true,"tier":"moderate"}},"grade_bf":{"id":"grade_bf","kind":"grade","label":"GRADE certainty for body fat percentage","quote":"the evidence about FM and BF% was downgraded to medium and low levels, respectively"},"grade_ffm":{"id":"grade_ffm","kind":"grade","label":"GRADE certainty for fat-free mass","quote":"which indicated the effect of FFM to be of high quality"},"grade_fm":{"id":"grade_fm","kind":"grade","label":"GRADE certainty for fat mass","quote":"the evidence about FM and BF% was downgraded to medium and low levels, respectively"},"joints":{"id":"joints","kind":"context","label":"Why running may suit heavier bodies less well","quote":"overweight and individuals with obesity exhibit altered joint loads, absolute ground reaction forces, and forefoot pressures compared to non-obese adults"},"lim_heterogeneity":{"id":"lim_heterogeneity","kind":"limitation","label":"Trials disagreed, especially on body fat percentage","quote":"significant heterogeneity (I) was found across studies, particularly with BF%"},"lim_loo":{"id":"lim_loo","kind":"limitation","label":"The fat-free-mass result depends on a single trial","quote":"the removal of one study [] in particular eliminated any observed significant overall effect of HIIT on FFM (WMD: −0.46, 95% CI: −1.38 to 0.44)"},"lim_methods":{"id":"lim_methods","kind":"limitation","label":"Body composition was measured in different ways","quote":"BF%, FM, and FFM were measured using different methodologies (e.g., subcutaneous skinfold caliper, ADP, BIA, and DEXA)"},"lim_population":{"id":"lim_population","kind":"limitation","label":"Most trials were in inactive adults who were overweight or obese","quote":"Primarily, a majority of investigations were conducted on overweight or obese inactive adults as opposed to active normal body mass or BMI adults."},"recipe":{"id":"recipe","kind":"statement","label":"The programme settings the authors found more effective","quote":"These data suggest that training for more than 8 weeks, at least three sessions per week, lower than 60 s work intervals separated by ≤90 s recovery periods, and active rest (instead of passive) are more effective on body composition."},"sample":{"id":"sample","kind":"context","label":"Total participants and mean age","quote":"These trials had a total sample size of 1130 individuals, and the mean age was 26.27 ± 5.42 years."},"subgroups":{"id":"subgroups","kind":"context","label":"Subgroup analyses were used","quote":"To find probable sources of heterogeneity, subgroup analyses were performed according to predefined variables"},"trials":{"id":"trials","kind":"context","label":"Number and length of the included trials","quote":"Thirty-six RCTs lasting between 3 to 15 weeks were included in the current systematic review and meta-analysis."},"wewege":{"id":"wewege","kind":"context","label":"An earlier meta-analysis with a different result for cycling","quote":"a systematic review and meta-analysis by Wewege et al. [] found no significant effect of cycling on measures of body composition (whole-body FM) in overweight and obese adults"}},"context":{"studies":[],"concepts":[{"slug":"fat-free-mass","term":"fat-free mass","plain":"Everything in your body that is not fat: muscle, bone, organs, blood and the water in and around your cells. A body scan can split your weight into fat and this rest; an ordinary bathroom scale cannot.","model":"Two piles on the scale: a fat pile and a pile of everything else. An ordinary bathroom scale only reads the two together.","reference":{"doi":"10.1093/ajcn/56.1.19","title":"The five-level model: a new approach to organizing body-composition research"}}]}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', 'key_takeaways', '{"takeaways":[[{"text":"If lean mass is the aim, the supported combination in these trials was cycling intervals, three sessions a week, for more than 8 weeks.","refs":["ffm_cycling","ffm_3wk","ffm_over8"]}],[{"text":"Keep work bursts to 60 seconds or less: longer bursts showed no clear gain in fat-free mass, with an interval from 2.28 kg lost to 0.57 kg gained.","refs":["ffm_le60","ffm_gt60"]}],[{"text":"Keep moving during the rest.","refs":["ffm_active"]},{"text":"Standing still between bursts showed no clear gain in fat-free mass.","refs":["ffm_passive"]}],[{"text":"Two sessions a week did not clearly change body fat percentage; three did.","refs":["bf_2wk","bf_3wk"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
