  ('e196fd35-6582-5c15-b8fd-f65c181f80da', '8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', 6, 'Intervals done as overground running', 'Body-fat track', 'condition', 'low', 'Body fat percentage −2.80 points (95% CI −3.89 to −1.71)', null, null, 'modality_is', '{"modality":"running"}'::jsonb, '{"fat":"on"}'::jsonb, null),
  ('e648c185-7433-5bf2-b9bf-325cc3b1392f', '8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', 7, 'More than 8 weeks into the block', 'Body-fat track', 'condition', 'low', 'Body fat percentage −2.08 points (95% CI −2.40 to −1.76)', null, null, 'block_weeks_gte', '{"weeks":8}'::jsonb, '{"fat":"on"}'::jsonb, null)
