    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- sleep-extension-energy-intake
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('472df157-9728-5fb6-b28a-0335e8e1e6a4', 'sleep-extension-energy-intake', 'Two weeks of longer sleep at home: what 80 adults then ate', '10.1001/jamainternmed.2021.8098', 'Sleep', 'The trial took 80 adults with overweight who slept under 6.5 hours a night. Sleep advice gave the sleep group 1.2 hours more sleep a night than the control group. Over 2 weeks they ate 270.4 kcal a day less than the control group, with no diet. Part of that gap came from the control group eating more than before.', 'free', '2026-11-19T06:41:02.465Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('472df157-9728-5fb6-b28a-0335e8e1e6a4', '{"hook":[{"text":"This trial gave 80 adults no diet and no exercise plan.","refs":["overall_mean_age","free_living_routine"]},{"text":"It aimed to change one thing, their time in bed, and then measured what they ate.","refs":["sleep_extension_target","energy_intake_method"]}],"populationPanel":[{"text":"Who was studied: 80 adults aged 21 to 40 with overweight (a BMI of 25.0 to 29.9).","refs":["overall_mean_age","eligibility_age_bmi_sleep"]},{"text":"They usually slept less than 6.5 hours a night.","refs":["eligibility_age_bmi_sleep"]},{"text":"Chance put each of them into longer sleep or their usual schedule, for 2 weeks at home.","refs":["randomization_method","baseline_and_intervention_periods","free_living_routine"]},{"text":"People with sleep apnea, insomnia or recent shift work could not take part.","refs":["exclusion_sleep_disorders_shift"]}],"sections":[],"limitations":[],"layers":{"mechanism":{"paragraphs":[[{"text":"Think of your weight as a ledger with two columns.","refs":[]},{"text":"Food goes into one column.","refs":[]},{"text":"The energy people burn, at rest and on the move, goes into the other.","refs":["energy_intake_method"]}],[{"text":"Short sleep tips that ledger.","refs":["prior_lab_sleep_restriction_range"]},{"text":"In laboratory studies, people whose sleep was cut ate about 250 to 350 kcal a day more, and burned about the same.","refs":["prior_lab_sleep_restriction_range"]}],[{"text":"This trial asked the question the other way round, at home.","refs":["free_living_routine"]},{"text":"Adults who extended their sleep ate less, while the energy they burned showed no clear difference.","refs":["ei_ext_change","tee_diff_in_changes"]},{"text":"Each extra hour of sleep went with about 162 kcal a day less food.","refs":["energy_intake_per_hour_sleep"]}],[{"text":"With less coming in and no clear change going out, the ledger moved the other way.","refs":["eb_diff_in_changes"]},{"text":"Over 2 weeks, the sleep group lost 0.48 kg, while the control group gained 0.39 kg.","refs":["baseline_and_intervention_periods","wt_ext_change","wt_ctrl_change"]}]],"figure":{"figure":"energy-ledger","caption":[{"text":"Change from each group’s usual 2 weeks, as the paper measured it.","refs":["baseline_and_intervention_periods"]}],"alt":"Two groups of adults, one above the other, each with a bar for food eaten and a bar for energy burned. In the longer-sleep group, the food bar falls below no change and the energy-burned bar dips much less. In the usual-sleep group, the food bar rises and the energy-burned bar barely moves. Under each group sits its change in weight.","params":{"title":"Food in, energy out","unit":"Change from each group’s usual weeks, kcal a day","less":"Less","noChange":"No change","more":"More","food":"Food eaten","burned":"Energy burned","weight":"Weight","groups":[{"label":"Longer sleep","food":{"kind":"measured","fact":{"id":"ei_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in energy intake","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in energy intake, sleep extension group","measure":"MD","point":-155.5,"ciLow":-244.1,"ciHigh":-66.9,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"burned":{"kind":"measured","fact":{"id":"tee_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in total energy expenditure","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in total energy expenditure, sleep extension group","measure":"MD","point":-46.7,"ciLow":-105.1,"ciHigh":11.6,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"weight":{"kind":"measured","fact":{"id":"wt_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in weight","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in weight, sleep extension group","measure":"MD","point":-0.48,"ciLow":-0.85,"ciHigh":-0.11,"unit":"kg","absolute":true,"tier":"moderate"}}}},{"label":"Usual sleep (the control group)","food":{"kind":"measured","fact":{"id":"ei_ctrl_change","kind":"estimate","label":"Control group change from baseline in energy intake","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in energy intake, control group","measure":"MD","point":114.9,"ciLow":29.6,"ciHigh":200.2,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"burned":{"kind":"measured","fact":{"id":"tee_ctrl_change","kind":"estimate","label":"Control group change from baseline in total energy expenditure","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in total energy expenditure, control group","measure":"MD","point":7.2,"ciLow":-49,"ciHigh":63.3,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"weight":{"kind":"measured","fact":{"id":"wt_ctrl_change","kind":"estimate","label":"Control group change from baseline in weight","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in weight, control group","measure":"MD","point":0.39,"ciLow":0.02,"ciHigh":0.76,"unit":"kg","absolute":true,"tier":"moderate"}}}}]}}},"protocol":{"paragraphs":[[{"text":"For 2 weeks, everyone kept their usual sleep at home.","refs":["baseline_and_intervention_periods"]},{"text":"Then chance split them into 2 groups for 2 more weeks.","refs":["randomization_method","baseline_and_intervention_periods"]},{"text":"The sleep group had a personal sleep advice session, aiming for 8.5 hours in bed each night.","refs":["sleep_hygiene_counseling_delivery","sleep_extension_target"]}],[{"text":"Nobody got a diet or an exercise plan.","refs":["free_living_routine"]},{"text":"A wrist sensor recorded sleep for all 4 weeks.","refs":["sleep_monitoring_duration","actigraphy_device"]},{"text":"A home scale they could not read weighed them twice every morning.","refs":["hidden_scale_weights"]},{"text":"Researchers measured the energy participants burned, and worked out food eaten from that plus changes in body stores.","refs":["dlw_method","energy_intake_method","body_energy_stores_method"]}]],"figure":null},"audit":{"effect":[{"text":"Change in daily energy intake, sleep group against control: 270.4 kcal a day lower (P < .001).","refs":["ei_diff_in_changes","ei_p_value"]}],"weakEnd":[{"text":"The 95% confidence interval runs from 393.4 to 147.4 kcal a day lower.","refs":["ei_diff_in_changes"]},{"text":"Even at the weak end, the sleep group ate 147.4 kcal a day less.","refs":["ei_diff_in_changes"]}],"limitations":[[{"text":"The control group’s rise in intake and weight may have added to the gap.","refs":["limit_control_increase"]}],[{"text":"The change lasted 2 weeks, so nobody knows how long people keep the longer nights.","refs":["baseline_and_intervention_periods","limit_short_duration_sustainability"]}],[{"text":"The method that measured the energy participants burned is precise to about 5%, which adds uncertainty to each intake figure.","refs":["limit_dlw_precision"]}],[{"text":"Only adults with overweight who met strict rules took part, so the result may not hold for others.","refs":["limit_generalizability"]}]],"missed":[{"text":"Both groups moved: intake fell by 155.5 kcal a day in the sleep group and rose by 114.9 in the control group.","refs":["ei_ext_change","ei_ctrl_change"]},{"text":"Of the 0.87 kg weight gap, 0.62 kg was fat-free mass and 0.25 kg was fat.","refs":["wt_diff_in_changes","ffm_diff_in_changes","fm_diff_in_changes"]}],"more":[[{"text":"Total energy participants burned (53.9 kcal a day, P = .19) and energy burned through activity showed no clear difference.","refs":["tee_diff_in_changes","tee_p_value","aee_day_p_value"]}],[{"text":"At rest while fasting, participants in the sleep group burned 32.5 kcal a day less (P = .047); after a meal there was no clear difference (P = .41).","refs":["rmr_fast_diff_in_changes","rmr_fast_p_value","rmr_post_p_value"]}],[{"text":"75 of 80 (93.8%) had complete intake data (sleep group 90.0%, control group 97.5%).","refs":["overall_mean_age","complete_ei_data_overall","complete_ei_by_group"]}],[{"text":"A weight model predicts about 12 kg lost over 3 years if a drop of about 270 kcal a day lasted; the trial did not test that.","refs":["hall_model_prediction"]}],[{"text":"Funded by the US National Institutes of Health; no conflicts of interest reported.","refs":["funding_sources","conflict_of_interest"]}]],"figure":null}},"glossary":[{"term":"BMI","plain":"Body mass index: weight in kilograms divided by height in metres squared, a rough measure of body size.","refs":["eligibility_age_bmi_sleep"],"concept":null},{"term":"kcal","plain":"Kilocalories, the unit of food energy that labels usually just call calories.","refs":["ei_diff_in_changes"],"concept":null},{"term":"fat-free mass","plain":"Everything in your body that is not fat: muscle, bone, organs, blood and the water in and around your cells. A body scan can split your weight into fat and this rest; an ordinary bathroom scale cannot.","refs":[],"concept":"fat-free-mass"}],"primaryEstimate":"ei_diff_in_changes","finding":{"question":[{"text":"Do adults eat less when they sleep longer at home?","refs":["sleep_extension_target","ei_diff_in_changes"]}],"headline":[{"text":"Compared with the control group, adults who slept longer ate 270.4 kcal a day less.","refs":["ei_diff_in_changes"]}],"support":[{"text":"The energy adults burned showed no clear difference between the groups.","refs":["tee_diff_in_changes","tee_p_value"]}]},"simulator":{"kind":"estimate-explorer","params":{"lowLabel":"Lower with longer sleep","highLabel":"Higher with longer sleep","rows":[{"label":"Food eaten (kcal a day)","fact":{"id":"ei_diff_in_changes","kind":"estimate","label":"Between-group difference in energy intake change","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in energy intake (sleep extension minus control)","measure":"MD","point":-270.4,"ciLow":-393.4,"ciHigh":-147.4,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},{"label":"Energy balance (kcal a day)","fact":{"id":"eb_diff_in_changes","kind":"estimate","label":"Between-group difference in energy balance change","quote":"Energy balance, kcal/d | −0.6 (−69.9 to 68.8) | 105.4 (36.0 to 174.8) | 106.0 (19.0 to 193.0) | 105.4 (36.9 to 174.0) | 0.4 (−71.7 to 72.4) | −105.1 (−193.8 to −16.3) | −211.1 (−335.4 to −86.8) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in energy balance","measure":"MD","point":-211.1,"ciLow":-335.4,"ciHigh":-86.8,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},{"label":"Total energy burned (kcal a day)","fact":{"id":"tee_diff_in_changes","kind":"estimate","label":"Between-group difference in total energy expenditure change","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in total energy expenditure","measure":"MD","point":-53.9,"ciLow":-134.9,"ciHigh":27.1,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},{"label":"Energy burned through activity (kcal a day)","fact":{"id":"aee_day_diff_in_changes","kind":"estimate","label":"Between-group difference in activity energy expenditure change (kcal/d)","quote":"Activity energy expenditure, kcal/d | 878.9 (759.7 to 998.0) | 863.7 (743.2 to 984.1) | −15.2 (−81.0 to 50.5) | 951.2 (832.8 to 1069.7) | 918.1 (798.8 to 1037.5) | −33.1 (−100.5 to 34.3) | −17.9 (−112.1 to 76.3) | .71 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in activity energy expenditure","measure":"MD","point":-17.9,"ciLow":-112.1,"ciHigh":76.3,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},{"label":"Resting energy burned, fasting (kcal a day)","fact":{"id":"rmr_fast_diff_in_changes","kind":"estimate","label":"Between-group difference in fasting resting metabolic rate change","quote":"Fasting | 1563.6 (1487.3 to 1640.0) | 1581.1 (1504.5 to 1657.6) | 17.4 (−4.9 to 39.7) | 1667.8 (1591.3 to 1744.2) | 1652.7 (1576.2 to 1729.3) | −15.1 (−38.0 to 7.9) | −32.5 (−64.5 to −0.5) | .047 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in fasting resting metabolic rate","measure":"MD","point":-32.5,"ciLow":-64.5,"ciHigh":-0.5,"unit":"kcal/d","absolute":true,"tier":"moderate"}}}]}},"glance":{"figure":{"figure":"energy-ledger","caption":[],"alt":"Food eaten and energy burned by adults in each group, drawn as bars.","params":{"title":"Food in, energy out","unit":"Change from each group’s usual weeks, kcal a day","less":"Less","noChange":"No change","more":"More","food":"Food eaten","burned":"Energy burned","weight":"Weight","groups":[{"label":"Longer sleep","food":{"kind":"measured","fact":{"id":"ei_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in energy intake","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in energy intake, sleep extension group","measure":"MD","point":-155.5,"ciLow":-244.1,"ciHigh":-66.9,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"burned":{"kind":"measured","fact":{"id":"tee_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in total energy expenditure","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in total energy expenditure, sleep extension group","measure":"MD","point":-46.7,"ciLow":-105.1,"ciHigh":11.6,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"weight":{"kind":"measured","fact":{"id":"wt_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in weight","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in weight, sleep extension group","measure":"MD","point":-0.48,"ciLow":-0.85,"ciHigh":-0.11,"unit":"kg","absolute":true,"tier":"moderate"}}}},{"label":"Usual sleep (the control group)","food":{"kind":"measured","fact":{"id":"ei_ctrl_change","kind":"estimate","label":"Control group change from baseline in energy intake","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in energy intake, control group","measure":"MD","point":114.9,"ciLow":29.6,"ciHigh":200.2,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"burned":{"kind":"measured","fact":{"id":"tee_ctrl_change","kind":"estimate","label":"Control group change from baseline in total energy expenditure","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in total energy expenditure, control group","measure":"MD","point":7.2,"ciLow":-49,"ciHigh":63.3,"unit":"kcal/d","absolute":true,"tier":"moderate"}}},"weight":{"kind":"measured","fact":{"id":"wt_ctrl_change","kind":"estimate","label":"Control group change from baseline in weight","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in weight, control group","measure":"MD","point":0.39,"ciLow":0.02,"ciHigh":0.76,"unit":"kg","absolute":true,"tier":"moderate"}}}}]}},"x":[{"text":"Change from their usual weeks","refs":[]}],"y":[],"alt":[{"text":"Food eaten and energy burned by adults in each group, drawn as bars.","refs":["energy_intake_method","dlw_method"]}],"note":[{"text":"Drawn from the paper’s own measurements.","refs":[]}],"tryIt":[{"text":"compare every energy estimate","refs":[]}]},"sourceLine":"80 adults aged 21 to 40 with overweight · randomized trial · 2 weeks of usual sleep, then 2 weeks of the change","facts":{"actigraphy_device":{"id":"actigraphy_device","kind":"context","label":"Wrist actigraphy device and software","quote":"Participants were asked to wear an accelerometer (motion)-based monitor (Actiwatch Spectrum Plus; Philips) and to press a built-in event marker button when they went to bed to sleep each night and when they got out of bed each morning."},"aee_day_p_value":{"id":"aee_day_p_value","kind":"finding","label":"P value for difference in activity energy expenditure change (kcal/d)","quote":"Activity energy expenditure, kcal/d | 878.9 (759.7 to 998.0) | 863.7 (743.2 to 984.1) | −15.2 (−81.0 to 50.5) | 951.2 (832.8 to 1069.7) | 918.1 (798.8 to 1037.5) | −33.1 (−100.5 to 34.3) | −17.9 (−112.1 to 76.3) | .71 |","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Activity energy expenditure (kcal/d)","tier":"moderate"}},"baseline_and_intervention_periods":{"id":"baseline_and_intervention_periods","kind":"context","label":"Baseline and intervention arm durations","quote":"After a 2-week habitual sleep period at baseline, participants were randomized to either 2-week sleep extension (sleep extension group) or 2-week continued habitual sleep (control group) (Figure 1)."},"body_energy_stores_method":{"id":"body_energy_stores_method","kind":"context","label":"Assessment of change in body energy stores","quote":"For each 2-week period, the change in body energy stores was computed from the regression (slope, grams per day) of daily home weights and change in body composition (ie, fat mass and fat-free mass) using dual-energy x-ray absorptiometry."},"complete_ei_by_group":{"id":"complete_ei_by_group","kind":"finding","label":"Completeness of energy intake data by group","quote":"The proportion of participants with complete data on energy intake was not significantly different between the sleep extension and control groups (90.0% vs 97.5%; P = .36).","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Completeness of energy intake data","tier":"moderate"}},"complete_ei_data_overall":{"id":"complete_ei_data_overall","kind":"finding","label":"Participants with complete primary outcome data","quote":"No statistically significant differences in baseline characteristics were found between the 75 participants (93.8%) who had complete data on energy intake (primary outcome) vs participants with missing data on energy intake.","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Baseline characteristics by primary outcome completeness","tier":"moderate"}},"conflict_of_interest":{"id":"conflict_of_interest","kind":"context","label":"Conflict of interest disclosures","quote":"Conflict of Interest Disclosures: None reported."},"dlw_method":{"id":"dlw_method","kind":"context","label":"Measurement of total energy expenditure","quote":"Total energy expenditure was measured by the doubly labeled water method."},"eb_diff_in_changes":{"id":"eb_diff_in_changes","kind":"estimate","label":"Between-group difference in energy balance change","quote":"Energy balance, kcal/d | −0.6 (−69.9 to 68.8) | 105.4 (36.0 to 174.8) | 106.0 (19.0 to 193.0) | 105.4 (36.9 to 174.0) | 0.4 (−71.7 to 72.4) | −105.1 (−193.8 to −16.3) | −211.1 (−335.4 to −86.8) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in energy balance","measure":"MD","point":-211.1,"ciLow":-335.4,"ciHigh":-86.8,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"ei_ctrl_change":{"id":"ei_ctrl_change","kind":"estimate","label":"Control group change from baseline in energy intake","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in energy intake, control group","measure":"MD","point":114.9,"ciLow":29.6,"ciHigh":200.2,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"ei_diff_in_changes":{"id":"ei_diff_in_changes","kind":"estimate","label":"Between-group difference in energy intake change","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in energy intake (sleep extension minus control)","measure":"MD","point":-270.4,"ciLow":-393.4,"ciHigh":-147.4,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"ei_ext_change":{"id":"ei_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in energy intake","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in energy intake, sleep extension group","measure":"MD","point":-155.5,"ciLow":-244.1,"ciHigh":-66.9,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"ei_p_value":{"id":"ei_p_value","kind":"finding","label":"P value for difference in energy intake change","quote":"Energy intake, kcal/d | 2665.0 (2468.4 to 2861.6) | 2779.9 (2583.3 to 2976.5) | 114.9 (29.6 to 200.2) | 2976.6 (2782.5 to 3170.7) | 2821.1 (2625.1 to 3017.2) | −155.5 (−244.1 to −66.9) | −270.4 (−393.4 to −147.4) | <.001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Energy intake","tier":"moderate"}},"eligibility_age_bmi_sleep":{"id":"eligibility_age_bmi_sleep","kind":"context","label":"Inclusion criteria for age, BMI, and habitual sleep","quote":"Adult men and women aged 21 to 40 years with a body mass index (calculated as weight in kilograms divided by height in meters squared) between 25.0 and 29.9 and a mean habitual sleep duration of less than 6.5 hours per night were eligible."},"energy_intake_method":{"id":"energy_intake_method","kind":"context","label":"Objective assessment of energy intake","quote":"For each 2-week period, the energy intake was calculated from the sum of total energy expenditure and change in body energy stores using the principle of energy balance."},"energy_intake_per_hour_sleep":{"id":"energy_intake_per_hour_sleep","kind":"finding","label":"Change in energy intake per 1-hour increase in sleep duration","quote":"Each 1-hour increase in sleep duration was associated with a decrease in energy intake of approximately 162 kcal/d (−162.3 kcal/d; 95% CI, −246.8 to −77.7 kcal/d; P < .001).","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Energy intake change per 1-hour sleep duration increase","tier":"moderate"}},"exclusion_sleep_disorders_shift":{"id":"exclusion_sleep_disorders_shift","kind":"context","label":"Exclusion criteria for sleep disorders and shift work","quote":"Those who had obstructive sleep apnea confirmed by laboratory polysomnography (apnea-hypopnea index >5), insomnia or history of any other sleep disorder, or night shift and rotating shift work (current or in the past 2 years) were excluded."},"ffm_diff_in_changes":{"id":"ffm_diff_in_changes","kind":"estimate","label":"Between-group difference in fat-free mass change","quote":"Fat-free mass change, kg | −0.05 (−0.27 to 0.17) | 0.22 (−0.003 to 0.44) | 0.26 (−0.01 to 0.54) | 0.32 (0.11 to 0.54) | −0.03 (−0.26 to 0.19) | −0.36 (−0.64 to −0.08) | −0.62 (−1.02 to −0.23) | .002 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in fat-free mass change","measure":"MD","point":-0.62,"ciLow":-1.02,"ciHigh":-0.23,"unit":"kg","absolute":true,"tier":"moderate"}},"fm_diff_in_changes":{"id":"fm_diff_in_changes","kind":"estimate","label":"Between-group difference in fat mass change","quote":"Fat mass change, kg | 0.004 (−0.08 to 0.09) | 0.13 (0.05 to 0.21) | 0.13 (0.03 to 0.23) | 0.12 (0.04 to 0.20) | −0.00 (−0.08 to 0.08) | −0.12 (−0.22 to −0.02) | −0.25 (−0.39 to −0.10) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in fat mass change","measure":"MD","point":-0.25,"ciLow":-0.39,"ciHigh":-0.1,"unit":"kg","absolute":true,"tier":"moderate"}},"free_living_routine":{"id":"free_living_routine","kind":"context","label":"No prescribed diet or physical activity","quote":"Participants continued their daily routine activities at home without any prescribed diet or physical activity."},"funding_sources":{"id":"funding_sources","kind":"context","label":"Study funding sources","quote":"Funding/Support: This study was funded by grants R01DK100426, CTSA-UL1 TR0002389, and UL1TR002389 from the National Institutes of Health and by the Diabetes Research and Training Center at The University of Chicago."},"hall_model_prediction":{"id":"hall_model_prediction","kind":"statement","label":"Hall dynamic prediction model for 270 kcal/d reduction","quote":"According to the Hall dynamic prediction model, a decrease in energy intake of approximately 270 kcal/d, which we observed after short-term sleep extension, would predict an approximately 12-kg weight loss over 3 years if the effects were sustained over a long term.,"},"hidden_scale_weights":{"id":"hidden_scale_weights","kind":"context","label":"Blinded home weight scale protocol","quote":"Participants were provided a cellular-enabled weight scale (BodyTrace; BodyTrace Inc) and instructed to take their nude weights twice every morning after awakening before eating or drinking. Weight values were hidden from the participants to minimize potential influence on behavior."},"limit_control_increase":{"id":"limit_control_increase","kind":"limitation","label":"Control group increases may have contributed to treatment effects","quote":"The increase in energy intake and weight from baseline that we observed in the control group may have contributed to the significant treatment effects."},"limit_dlw_precision":{"id":"limit_dlw_precision","kind":"limitation","label":"Precision limit of doubly labeled water method","quote":"The doubly labeled water method has a precision of 5%, which may translate into some degree of uncertainty in the energy intake calculations."},"limit_generalizability":{"id":"limit_generalizability","kind":"limitation","label":"Limited generalizability due to selective eligibility","quote":"We enrolled adults with overweight and used selective eligibility criteria, which may limit generalizability to more diverse populations."},"limit_short_duration_sustainability":{"id":"limit_short_duration_sustainability","kind":"limitation","label":"Unknown long-term sustainability of sleep habits","quote":"The study did not provide information on how long healthy sleep habits could be maintained over longer periods."},"limit_sleep_factors_unassessed":{"id":"limit_sleep_factors_unassessed","kind":"limitation","label":"Factors influencing sleep behavior not systematically assessed","quote":"We did not systematically assess the factors that may have influenced sleep behavior, but limiting the use of electronic devices appeared to be a key intervention among the participants (eTable 4 in Supplement 2)."},"overall_mean_age":{"id":"overall_mean_age","kind":"context","label":"Overall mean (SD) age of analyzed participants","quote":"The 80 participants had a mean (SD) age of 29.8 (5.1) years and consisted of 41 men (51.3%) and 39 women (48.7%)."},"prior_lab_sleep_restriction_range":{"id":"prior_lab_sleep_restriction_range","kind":"statement","label":"Earlier lab sleep restriction studies on energy intake","quote":"Short-term experimental laboratory studies have found that sleep restriction in healthy individuals is associated with an increased mean energy intake of about 250 to 350 kcal/d with minimal to no change in energy expenditure.,,, "},"randomization_method":{"id":"randomization_method","kind":"context","label":"Randomization blocking and stratification","quote":"Block randomization, stratified by sex, was performed using computer-generated random numbers."},"rmr_fast_diff_in_changes":{"id":"rmr_fast_diff_in_changes","kind":"estimate","label":"Between-group difference in fasting resting metabolic rate change","quote":"Fasting | 1563.6 (1487.3 to 1640.0) | 1581.1 (1504.5 to 1657.6) | 17.4 (−4.9 to 39.7) | 1667.8 (1591.3 to 1744.2) | 1652.7 (1576.2 to 1729.3) | −15.1 (−38.0 to 7.9) | −32.5 (−64.5 to −0.5) | .047 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in fasting resting metabolic rate","measure":"MD","point":-32.5,"ciLow":-64.5,"ciHigh":-0.5,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"rmr_fast_p_value":{"id":"rmr_fast_p_value","kind":"finding","label":"P value for difference in fasting resting metabolic rate change","quote":"Fasting | 1563.6 (1487.3 to 1640.0) | 1581.1 (1504.5 to 1657.6) | 17.4 (−4.9 to 39.7) | 1667.8 (1591.3 to 1744.2) | 1652.7 (1576.2 to 1729.3) | −15.1 (−38.0 to 7.9) | −32.5 (−64.5 to −0.5) | .047 |","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Fasting resting metabolic rate","tier":"moderate"}},"rmr_post_p_value":{"id":"rmr_post_p_value","kind":"finding","label":"P value for difference in postprandial resting metabolic rate change","quote":"Postprandial | 1837.9 (1746.6 to 1929.2) | 1859.7 (1768.0 to 1951.4) | 21.8 (−6.5 to 50.1) | 1944.9 (1853.4 to 2036.5) | 1949.8 (1858.1 to 2041.4) | 4.8 (−24.2 to 33.9) | −17.0 (−57.5 to 23.6) | .41 |","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Postprandial resting metabolic rate","tier":"moderate"}},"sleep_duration_diff":{"id":"sleep_duration_diff","kind":"estimate","label":"Between-group difference in change in mean sleep duration","quote":"Participants in the sleep extension group had a significant increase from baseline in mean sleep duration by actigraphy compared with those in the control group (1.2 hours; 95% CI, 1.0-1.4 hours; P < .001).","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in mean nightly sleep duration by actigraphy","measure":"MD","point":1.2,"ciLow":1,"ciHigh":1.4,"unit":"hours","absolute":true,"tier":"moderate"}},"sleep_extension_target":{"id":"sleep_extension_target","kind":"context","label":"Sleep extension counseling and bedtime target","quote":"At the end of the interview, participants were provided with individualized recommendations to follow at home for 2 weeks, with the aim of extending their bedtime duration to 8.5 hours."},"sleep_hygiene_counseling_delivery":{"id":"sleep_hygiene_counseling_delivery","kind":"context","label":"Sleep hygiene counseling delivery","quote":"Those who were randomized to the sleep extension group received individualized sleep hygiene counseling through a structured interview (E.T.) (eMethods in Supplement 2)."},"sleep_monitoring_duration":{"id":"sleep_monitoring_duration","kind":"context","label":"Sleep monitoring duration","quote":"Sleep-wake patterns were continuously monitored at home by wrist actigraphy throughout the 4-week study."},"tee_ctrl_change":{"id":"tee_ctrl_change","kind":"estimate","label":"Control group change from baseline in total energy expenditure","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in total energy expenditure, control group","measure":"MD","point":7.2,"ciLow":-49,"ciHigh":63.3,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"tee_diff_in_changes":{"id":"tee_diff_in_changes","kind":"estimate","label":"Between-group difference in total energy expenditure change","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in change in total energy expenditure","measure":"MD","point":-53.9,"ciLow":-134.9,"ciHigh":27.1,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"tee_ext_change":{"id":"tee_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in total energy expenditure","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in total energy expenditure, sleep extension group","measure":"MD","point":-46.7,"ciLow":-105.1,"ciHigh":11.6,"unit":"kcal/d","absolute":true,"tier":"moderate"}},"tee_p_value":{"id":"tee_p_value","kind":"finding","label":"P value for difference in total energy expenditure change","quote":"Total energy expenditure, kcal/d | 2693.5 (2499.9 to 2887.1) | 2700.7 (2507.1 to 2894.3) | 7.2 (−49.0 to 63.3) | 2871.1 (2677.6 to 3064.7) | 2824.4 (2630.2 to 3018.6) | −46.7 (−105.1 to 11.6) | −53.9 (−134.9 to 27.1) | .19 |","why":"People were assigned at random, which rules out most other explanations, in one study.","finding":{"outcome":"Total energy expenditure","tier":"moderate"}},"wt_ctrl_change":{"id":"wt_ctrl_change","kind":"estimate","label":"Control group change from baseline in weight","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in weight, control group","measure":"MD","point":0.39,"ciLow":0.02,"ciHigh":0.76,"unit":"kg","absolute":true,"tier":"moderate"}},"wt_diff_in_changes":{"id":"wt_diff_in_changes","kind":"estimate","label":"Between-group difference in weight change","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Difference in weight change (sleep extension minus control)","measure":"MD","point":-0.87,"ciLow":-1.39,"ciHigh":-0.35,"unit":"kg","absolute":true,"tier":"moderate"}},"wt_ext_change":{"id":"wt_ext_change","kind":"estimate","label":"Sleep extension group change from baseline in weight","quote":"Weight change, kgc | −0.04 (−0.33 to 0.25) | 0.35 (0.06 to 0.64) | 0.39 (0.02 to 0.76) | 0.45 (0.16 to 0.73) | −0.03 (−0.33 to 0.27) | −0.48 (−0.85 to −0.11) | −0.87 (−1.39 to −0.35) | .001 |","why":"People were assigned at random, which rules out most other explanations, in one study.","estimate":{"outcome":"Change from baseline in weight, sleep extension group","measure":"MD","point":-0.48,"ciLow":-0.85,"ciHigh":-0.11,"unit":"kg","absolute":true,"tier":"moderate"}}},"context":{"studies":[],"concepts":[{"slug":"fat-free-mass","term":"fat-free mass","plain":"Everything in your body that is not fat: muscle, bone, organs, blood and the water in and around your cells. A body scan can split your weight into fat and this rest; an ordinary bathroom scale cannot.","model":"Two piles on the scale: a fat pile and a pile of everything else. An ordinary bathroom scale only reads the two together.","reference":{"doi":"10.1093/ajcn/56.1.19","title":"The five-level model: a new approach to organizing body-composition research"}}]}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('472df157-9728-5fb6-b28a-0335e8e1e6a4', 'key_takeaways', '{"takeaways":[[{"text":"Aiming for 8.5 hours in bed, adults who had slept under 6.5 hours got 1.2 hours more sleep than the control group.","refs":["eligibility_age_bmi_sleep","sleep_extension_target","sleep_duration_diff"]}],[{"text":"Compared with the control group, they ate 270.4 kcal a day less, with no diet.","refs":["ei_diff_in_changes","free_living_routine"]}],[{"text":"The authors noted that limiting electronic devices seemed to matter to participants; the trial did not test it on its own.","refs":["limit_sleep_factors_unassessed"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('484d201b-e28f-553e-8659-40b1b25e4d1c', '472df157-9728-5fb6-b28a-0335e8e1e6a4', 1, '8.5 hours in bed tonight', 'Set a bedtime that leaves 8.5 hours in bed, the trial’s target. A tick records the bedtime, not your sleep.', 'action', 'moderate', 'Difference in change in energy intake (sleep extension minus control) −270.4 kcal/d (95% CI −393.4 to −147.4)', null, null, null, null, null, null),
  ('a1c802b3-8417-52d0-9f10-6ad1407c9a7b', '472df157-9728-5fb6-b28a-0335e8e1e6a4', 2, 'Devices away before bed', 'The authors noted this seemed to be a key change for participants. The trial did not test it on its own, so it carries no weight.', 'action', 'none', null, null, null, null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- steps-days-per-week
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('58929ab5-72ec-5a41-941b-be5f29965932', 'steps-days-per-week', '8,000 steps on one or two days a week: what ten years of death records show', '10.1001/jamanetworkopen.2023.5174', 'Movement', 'Among 3,101 US adults, reaching 8,000 steps on only 1 to 2 days a week was associated with a 10-year risk of death 14.9 points lower than never reaching it. The comparison is less clean than it sounds.', 'free', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('58929ab5-72ec-5a41-941b-be5f29965932', '{"hook":[{"text":"Step counts are usually sold as a daily target.","refs":[]},{"text":"This study asked a different question: does it matter on how many days of the week you get there?","refs":["threshold"]}],"populationPanel":[{"text":"Who was studied: 3,101 US adults aged 20 or older who wore a step counter for 1 week in 2005-2006.","refs":["sample","cohort"]},{"text":"National death records then followed them.","refs":["cohort"]},{"text":"Nobody was assigned to walk more or less, so this is an observational study.","refs":["cohort"]},{"text":"It describes these adults. It is not a prescription.","refs":[]}],"sections":[],"limitations":[],"layers":{"mechanism":{"paragraphs":[[{"text":"Picture a ramp that falls steeply, then levels off.","refs":[]},{"text":"The biggest gap in risk sits between people with no 8,000-step days and people with one or two.","refs":["ard_1_2","ard_3_7","threshold"]},{"text":"Past three or four such days a week, the curve was nearly flat.","refs":["plateau"]}],[{"text":"The same shape shows up for steps per day.","refs":["parallel_meta"]},{"text":"In an earlier pooled analysis, risk stopped falling at 6,000 to 8,000 steps a day for adults over 60.","refs":["parallel_meta"]},{"text":"For younger adults it stopped at 8,000 to 10,000.","refs":["parallel_meta"]}],[{"text":"Studies of exercise point the same way.","refs":["nhis_prior"]},{"text":"In a large US survey, death risks showed no clear difference between weekend-only exercisers and people active all week.","refs":["nhis_prior"]}],[{"text":"So 8,000 is a handy marker, not a magic line.","refs":["thresholds","threshold"]},{"text":"Any daily cut-off from 6,000 to 10,000 steps gave similar results.","refs":["thresholds"]}]],"figure":null},"protocol":{"paragraphs":[[{"text":"The study counted days, not daily totals.","refs":["threshold"]},{"text":"People wore a step counter for one week.","refs":["cohort"]},{"text":"Researchers then sorted them by how many days they reached 8,000 steps: none, 1 to 2, or 3 to 7.","refs":["threshold"]},{"text":"National death records followed them for about 10 years.","refs":["cohort","followup"]}],[{"text":"The researchers allowed for age, health and habits.","refs":["models"]},{"text":"After that, people with 1 to 2 such days had a 10-year risk of death 14.9 points lower than people with none.","refs":["ard_1_2","followup"]},{"text":"With 3 to 7 days it was 16.5 points, only a little more.","refs":["ard_3_7"]}]],"figure":null},"audit":{"effect":[{"text":"Adjusted risk difference, 1 to 2 days against none: a 10-year risk of death 14.9 points lower.","refs":["ard_1_2","followup"]}],"weakEnd":[{"text":"The 95% confidence interval runs from 18.8 points to 10.9 points lower.","refs":["ard_1_2"]},{"text":"Even the weak end, 10.9 points, is a wide gap for a study of deaths.","refs":["ard_1_2"]},{"text":"The range cannot say whether the walking is the reason.","refs":["ard_1_2"]}],"limitations":[[{"text":"The study counted steps for one week only, at the start.","refs":["one_week"]},{"text":"How these people walked over the next 10 years is unknown.","refs":["one_week","followup"]}],[{"text":"This is an observational study.","refs":["cohort"]},{"text":"Poor health can mean fewer steps and an earlier death, and no adjustment removes that fully.","refs":["confounding"]}],[{"text":"Wearing a tracker can make people more active that week, putting some usually inactive people in the wrong group.","refs":["hawthorne","reactivity_misclassification"]}]],"missed":[{"text":"The adjusted gap was 7.4 points in adults under 65 and 19.9 points in those 65 and over.","refs":["ard_1_2_under65","ard_1_2_65plus"]},{"text":"The adjustments shrank it: 18.7 points with age and sex alone, 14.9 with everything.","refs":["ard_1_2_agesex","ard_1_2"]}],"more":[[{"text":"Heart and blood vessel deaths showed the same pattern: 8.1 points lower for 1 to 2 days, 8.4 for 3 to 7.","refs":["cv_ard_1_2","cv_ard_3_7","threshold"]}],[{"text":"The study kept only people who wore the tracker for the week, which may bias the sample.","refs":["selection_bias"]}]],"figure":{"figure":"three-crowds","headline":[{"text":"The three groups were different people before anyone counted a step.","refs":["ages","mobility"]}],"caption":[{"text":"Poor health can affect both step counts and survival.","refs":["confounding"]},{"text":"The study adjusted for much of this, not all.","refs":["models","confounding"]},{"text":"Steps were counted for one week only.","refs":["one_week"]}],"alt":"Three columns, one for each group: no days, 1 to 2 days and 3 to 7 days a week at 8,000 steps or more. The average ages are 63.7, 51.5 and 46.0 years. The shares with trouble walking or climbing stairs are 50.5%, 20.3% and 6.8%.","params":{"threshold":{"n":8000,"ref":"threshold"},"mobilityWords":"had trouble walking or with stairs","groups":[{"from":{"n":0,"ref":"threshold"},"to":{"n":0,"ref":"threshold"},"age":{"n":63.7,"ref":"ages"},"mobility":{"n":50.5,"ref":"mobility"}},{"from":{"n":1,"ref":"threshold"},"to":{"n":2,"ref":"threshold"},"age":{"n":51.5,"ref":"ages"},"mobility":{"n":20.3,"ref":"mobility"}},{"from":{"n":3,"ref":"threshold"},"to":{"n":7,"ref":"threshold"},"age":{"n":46,"ref":"ages"},"mobility":{"n":6.8,"ref":"mobility"}}],"ages":{"kind":"measured","fact":{"id":"ages","kind":"descriptive","label":"Mean age of the three groups (0, 1-2, 3-7 days)","quote":"Age, mean (SD), y\n\n63.7 (19.3)\n\n51.5 (19.0)\n\n46.0 (15.5)"}},"mobility":{"kind":"measured","fact":{"id":"mobility","kind":"descriptive","label":"Number (%) with a mobility limitation in the three groups","quote":"Mobility limitation\n\n319 (50.5)\n\n108 (20.3)\n\n132 (6.8)"}}},"title":[{"text":"Why the raw gap is so wide","refs":[]}]}}},"glossary":[{"term":"step counter","plain":"A small device worn on the body that records movement; here it counted steps for a week.","refs":["cohort"],"concept":null},{"term":"adjustments","plain":"Allowances the researchers made for how the groups differed, such as age, smoking and illness, so that like is compared with like.","refs":["models"],"concept":null}],"primaryEstimate":"ard_1_2","finding":{"question":[{"text":"Do one or two 8,000-step days a week go with a longer life?","refs":["threshold"]}],"headline":[{"text":"People with 1–2 such days had a 14.9-point lower 10-year risk of death than people with none.","refs":["ard_1_2","followup","threshold"]}],"support":[{"text":"This is the difference after the study''s adjustments.","refs":["ard_1_2"]}]},"simulator":{"kind":"association-curve","params":{"groups":[{"from":{"n":0,"ref":"threshold"},"to":{"n":0,"ref":"threshold"},"meanAge":{"n":63.7,"ref":"ages"},"died":{"n":257,"ref":"crude_0"},"total":{"n":632,"ref":"crude_0"}},{"from":{"n":1,"ref":"threshold"},"to":{"n":2,"ref":"threshold"},"meanAge":{"n":51.5,"ref":"ages"},"died":{"n":75,"ref":"crude_1_2"},"total":{"n":532,"ref":"crude_1_2"}},{"from":{"n":3,"ref":"threshold"},"to":{"n":7,"ref":"threshold"},"meanAge":{"n":46,"ref":"ages"},"died":{"n":107,"ref":"crude_3_7"},"total":{"n":1937,"ref":"crude_3_7"}}],"event":"died","events":"deaths","years":{"n":10,"ref":"followup"},"plateau":{"id":"plateau","kind":"statement","label":"Where the curve flattened","quote":"the risk of mortality at 10 years rapidly decreased as the number of days per week taking 8000 steps or more increased and plateaued at 3 to 4 days"},"plateauLabel":"the authors: levelled off"},"spec":{"kind":"association-curve","facts":{"raw":[{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}}]},"simulator":{"raw":[{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}}],"adjusted":[{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}}]}},"words":{"alt":[{"text":"Three grids of dots, one for each group of days a week at 8,000 steps or more.","refs":["threshold"]},{"text":"Each dot is a person; a hollow dot is a person who died within 10 years, before any adjustment.","refs":["followup","crude_0","crude_1_2","crude_3_7"]},{"text":"Under the grids, two shaded ranges show each group''s adjusted difference from the group with no such days.","refs":["ard_1_2","ard_3_7"]}],"headline":[{"text":"Of the people who never reached 8,000 steps, 40.7% had died ten years on.","refs":["threshold","crude_0"]},{"text":"With 1–2 days a week, 14.1% had.","refs":["threshold","crude_1_2"]}],"ask":[{"text":"On how many days a week do you reach 8,000 steps?","refs":["threshold"]}],"who":[{"text":"3,101 US adults aged 20 or older wore a step counter for one week in 2005 and 2006, and national death records followed them afterwards.","refs":["sample","cohort"]}],"kept":[{"text":"Alive at 10 years","refs":["followup"]}],"happened":[{"text":"Died","refs":[]}],"later":[{"text":"10 years later","refs":["followup"]}],"rawNote":[{"text":"Raw counts.","refs":["crude_0","crude_1_2","crude_3_7"]},{"text":"The groups differ in age and health.","refs":["ages","mobility"]}],"stripTitle":[{"text":"After allowing for age, health and habits","refs":["models"]}],"stripUnder":[{"text":"Range for the study average.","refs":[]}],"plateau":[{"text":"The authors say the lower risk levelled off at 3–4 days.","refs":["plateau"]}]}},"glance":{"figure":null,"x":[{"text":"Days a week at the step goal","refs":[]}],"y":[],"alt":[{"text":"Two grids of dots, one for people who never reached the step goal and one for people who did on one or two days a week.","refs":["threshold"]},{"text":"Hollow dots are people who died within ten years, before any adjustment.","refs":["crude_0","crude_1_2"]}],"note":[{"text":"Each dot is a person, before any adjustment. Try it with your own week inside.","refs":[]}],"tryIt":[{"text":"find your group","refs":[]}]},"sourceLine":"3,101 US adults · observational cohort · followed for 10 years","facts":{"ages":{"id":"ages","kind":"descriptive","label":"Mean age of the three groups (0, 1-2, 3-7 days)","quote":"Age, mean (SD), y\n\n63.7 (19.3)\n\n51.5 (19.0)\n\n46.0 (15.5)"},"ard_1_2":{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_65plus":{"id":"ard_1_2_65plus","kind":"estimate","label":"Adjusted risk difference, 1-2 days, adults 65 and over","quote":"aged ≥65 years: aRD, −19.9% [95% CI, −30.8% to −8.9%]","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-19.9,"ciLow":-30.8,"ciHigh":-8.9,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_agesex":{"id":"ard_1_2_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 1-2 days, all-cause","quote":"−18.7 (−23.2 to −14.4)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-18.7,"ciLow":-23.2,"ciHigh":-14.4,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_under65":{"id":"ard_1_2_under65","kind":"estimate","label":"Adjusted risk difference, 1-2 days, adults under 65","quote":"aged <65 years: aRD, −7.4% [95% CI, −11.2% to −3.7%]","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-7.4,"ciLow":-11.2,"ciHigh":-3.7,"unit":"points","absolute":true,"tier":"low"}},"ard_3_7":{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}},"cohort":{"id":"cohort","kind":"context","label":"Who was enrolled, when, and how steps were measured","quote":"This cohort study evaluated a representative sample of participants aged 20 years or older in the National Health and Nutrition Examination Surveys 2005-2006 who wore an accelerometer for 1 week and their mortality data through December 31, 2019."},"confounding":{"id":"confounding","kind":"limitation","label":"Residual confounding by health status","quote":"our findings still have residual confounding bias (ie, poor health could influence daily step counts and mortality risk)"},"crude_0":{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"crude_1_2":{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"crude_3_7":{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"cv_ard_1_2":{"id":"cv_ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days, cardiovascular","quote":"(aRD, −8.1%; 95% CI, −11.8% to −4.4%)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.1,"ciLow":-11.8,"ciHigh":-4.4,"unit":"points","absolute":true,"tier":"low"}},"cv_ard_3_7":{"id":"cv_ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days, cardiovascular","quote":"(aRD, −8.4%; 95% CI, −12.5% to −4.4%)","why":"The study watched people without assigning anything, so other differences between them could explain the result.","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.4,"ciLow":-12.5,"ciHigh":-4.4,"unit":"points","absolute":true,"tier":"low"}},"followup":{"id":"followup","kind":"context","label":"Length of follow-up and number of deaths","quote":"Over the 10-year follow-up, all-cause and cardiovascular deaths occurred in 439 (14.2%) and 148 (5.3%) participants, respectively."},"hawthorne":{"id":"hawthorne","kind":"limitation","label":"People may walk more because they are wearing a tracker","quote":"as a result of knowledge that they are wearing the device, participants might have a tendency to be more active, a phenomenon known as the Hawthorne effect"},"mobility":{"id":"mobility","kind":"descriptive","label":"Number (%) with a mobility limitation in the three groups","quote":"Mobility limitation\n\n319 (50.5)\n\n108 (20.3)\n\n132 (6.8)"},"mobility_def":{"id":"mobility_def","kind":"context","label":"How mobility limitation was defined","quote":"Mobility limitations were defined as self-report of difficulty walking 0.25 miles without special equipment or climbing 10 stairs."},"models":{"id":"models","kind":"context","label":"What each adjustment model added","quote":"Model 1 included age; sex; race and ethnicity; insurance status; marital status; smoking; body mass index; estimated glomerular filtration rate; statin use; and history of diabetes, hypertension, cardiovascular disease, cancer, and emphysema. Model 2 included average daily step counts in addition to the covariates in model 1."},"nhis_prior":{"id":"nhis_prior","kind":"context","label":"Prior study in US National Health Interview Survey","quote":"A more recent study in 350 978 participants from the US National Health Interview Surveysupports these findings, wherein all-cause and cause-specific mortality risks did not differ between weekend warriors and regularly active participants, even after accounting for the total amount of moderate to vigorous physical activity."},"one_week":{"id":"one_week","kind":"limitation","label":"Steps measured for a single week","quote":"because daily steps were only measured for 1 week at baseline, we did not have information on how changes in physical activity contribute to risk of mortality"},"parallel_meta":{"id":"parallel_meta","kind":"context","label":"Earlier meta-analysis on steps per day and mortality, cited by the authors","quote":"a recent meta-analysis showed decreasing mortality risks with an increasing number of daily steps until 6000 to 8000 steps are reached for adults older than 60 years and at 8000 to 10 000 steps per day for those younger than 60 years"},"plateau":{"id":"plateau","kind":"statement","label":"Where the curve flattened","quote":"the risk of mortality at 10 years rapidly decreased as the number of days per week taking 8000 steps or more increased and plateaued at 3 to 4 days"},"reactivity_misclassification":{"id":"reactivity_misclassification","kind":"limitation","label":"Misclassification from Hawthorne reactivity","quote":"Such reactivity might cause misclassification such that some people who are typically physically inactive were categorized as physically active (based on a reaction to wearing the accelerometer) particularly because NHANES measured their daily step pattern for only 1 week."},"sample":{"id":"sample","kind":"context","label":"Number of participants","quote":"Among 3101 participants (mean [SD] age, 50.5 [18.4] years"},"selection_bias":{"id":"selection_bias","kind":"limitation","label":"Selection bias from accelerometer wear restriction","quote":"Fifth, our findings might suffer from selection bias due to restricting study samples to those who wore an accelerometer for 1 week during the survey."},"threshold":{"id":"threshold","kind":"context","label":"How participants were grouped","quote":"Participants were grouped by the number of days per week they took 8000 steps or more (0 days, 1-2 days, and 3-7 days)."},"thresholds":{"id":"thresholds","kind":"statement","label":"Other step thresholds gave similar results","quote":"Different thresholds for the number of daily steps between 6000 and 10 000 yielded similar results."}}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('58929ab5-72ec-5a41-941b-be5f29965932', 'key_takeaways', '{"takeaways":[[{"text":"If a daily target keeps failing, the study''s lowest active group is a reasonable place to start: 8,000 steps on 1 to 2 days a week.","refs":["threshold","ard_1_2"]}],[{"text":"Past 3 to 4 such days the association flattened, so a missed day is no reason to write off the week.","refs":["plateau"]}],[{"text":"The association was widest in adults aged 65 and over, at 19.9 points against 7.4 points in younger adults.","refs":["ard_1_2_65plus","ard_1_2_under65"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('cd120d77-53a2-59fd-8bef-41a28b033ee7', '58929ab5-72ec-5a41-941b-be5f29965932', 1, 'Reached 8,000 steps today', 'Tick on any day your tracker shows 8,000 or more. A log, not a daily requirement.', 'action', 'none', null, null, null, null, null, null, null),
  ('fe0a3b64-2766-50aa-848f-6730306c5c7c', '58929ab5-72ec-5a41-941b-be5f29965932', 2, '8,000 steps on at least 1 day this week', 'The study''s 1-to-2-day group.', 'weekly_target', 'low', '10-year risk of death from any cause −14.9 points (95% CI −18.8 to −10.9)', 1, 'cd120d77-53a2-59fd-8bef-41a28b033ee7', null, null, null, null),
  ('8ae27155-81be-5408-9d91-309329f4f1f0', '58929ab5-72ec-5a41-941b-be5f29965932', 3, '8,000 steps on at least 3 days this week', 'The study''s 3-to-7-day group, where the association went flat.', 'weekly_target', 'low', '10-year risk of death from any cause −16.5 points (95% CI −20.4 to −12.5)', 3, 'cd120d77-53a2-59fd-8bef-41a28b033ee7', null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- turmeric-pepper-breakfast
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('735a2dc7-8f80-59f4-afae-c49e591ae748', 'turmeric-pepper-breakfast', '1 g of black pepper in breakfast: what blood glucose did over the next 3 hours', '10.1002/fsn3.3965', 'Nutrition', 'Twenty healthy adults ate the same egg-and-toast breakfast four ways. With 1 g of black pepper in the egg, blood glucose was lower than after the plain meal. The clear difference was at the 30-minute reading. Added up over 3 hours, the meals did not differ.', 'free', '2026-11-13T13:46:30.346Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('735a2dc7-8f80-59f4-afae-c49e591ae748', '{"hook":[{"text":"1 g of black pepper in a breakfast egg, and blood glucose was lower than after the plain egg.","refs":["in_egg","glucose_lower"]},{"text":"The clear difference was at 30 minutes.","refs":["glucose_30"]},{"text":"Added up over the full 3 hours, there was no difference.","refs":["glucose_total","nothing_else"]}],"populationPanel":[{"text":"Who this was tested in: 20 healthy adults, 10 men and 10 women.","refs":["sample"]},{"text":"The women averaged 21.4 years old and the men 21.9.","refs":["ages"]},{"text":"The entry rules asked for a body mass index of 18.5 to 24.9 and no chronic disease.","refs":["criteria"]},{"text":"Each person ate all four breakfasts in randomized order, a week apart.","refs":["crossover","washout"]},{"text":"The result describes one meal in people like these.","refs":["single_meal","sample"]},{"text":"It says nothing about diabetes or any other disease.","refs":["criteria"]}],"sections":[],"limitations":[],"layers":{"mechanism":{"paragraphs":[[{"text":"Think of a doorbell in your mouth.","refs":[]},{"text":"Food presses it, and the rest of the body hears that a meal is on the way.","refs":[]},{"text":"The authors point to a real one: a sensor in the mouth called TRPV1.","refs":["trpv1_mouth"]},{"text":"Black pepper carries a compound called piperine and several close relatives.","refs":["piperine","trpv1"]},{"text":"The authors say these might press that sensor.","refs":["trpv1"]}],[{"text":"What happens next is a hormone.","refs":[]},{"text":"When TRPV1 fires, levels of a gut hormone called GLP-1 go up in the lower gut and in the blood.","refs":["glp1"]},{"text":"GLP-1 is the gut''s message that food has arrived.","refs":["glp1","concept:glucagon-like-peptide"]},{"text":"It helps hold down the rise in blood sugar after eating, slows the gut and curbs appetite.","refs":["concept:glucagon-like-peptide"]}],[{"text":"That chain fits what the trial saw.","refs":[]},{"text":"After the pepper breakfast, blood glucose was lower than after the plain one.","refs":["glucose_lower"]},{"text":"The gap showed at the 30-minute reading.","refs":["glucose_30"]},{"text":"Hunger was lower too.","refs":["appetite"]}],[{"text":"Turmeric did not follow the script.","refs":[]},{"text":"On its own, 1 g showed no clear difference in blood glucose.","refs":["turmeric_none"]},{"text":"The authors'' explanation is the dose: they call it low.","refs":["turmeric_dose"]}]],"figure":{"figure":"tongue-to-blood","headline":[{"text":"The authors think pepper switches on a sensor in the mouth, then a gut signal.","refs":["trpv1","trpv1_mouth","glp1"]},{"text":"They measured blood sugar, not the hormones.","refs":["glucose_lower","lim_hormones"]}],"caption":[{"text":"Dashed: the authors'' idea.","refs":["trpv1","glp1"]},{"text":"Solid: what the trial measured.","refs":["glucose_lower"]}],"alt":"Two rows of four drawings: a breakfast egg, a tongue, a loop of gut and a blood vessel. The top row is the plain egg; the bottom row has black pepper mixed into the egg. In the bottom row, dashed outlines show the authors'' idea: pepper switches on a mouth sensor, and a gut signal goes up. A solid arrow runs from the pepper egg to the blood: blood sugar was lower than after the plain egg. The clear difference was at 30 minutes.","params":{"title":"From the mouth to the blood: the authors'' idea and what was measured","rows":{"plain":"Plain egg","spiced":"Egg with pepper"},"sensor":{"name":"Sensor in the mouth","kind":"proposed","fact":{"id":"trpv1_mouth","kind":"statement","label":"TRPV1 is in the mouth; the authors say its activation is known to affect glucose control and appetite","quote":"TRPV1 is present in the oral cavity and its activation is widely known to improve glucose homeostasis, potentially affect appetite responses as well as increase energy metabolism."}},"signal":{"name":"The gut''s “food has arrived” signal","spiced":"May go up","kind":"proposed","fact":{"id":"glp1","kind":"statement","label":"TRPV1 activation raises GLP-1 in the lower small intestine and the blood (earlier work the authors cite)","quote":"Furthermore, TRPV1 activation increases GLP‐1; glucagon‐like peptide‐1 levels in the ileum and plasma."}},"links":[{"spiced":"Pepper may switch it on","kind":"proposed","fact":{"id":"trpv1","kind":"statement","label":"Authors'' proposed mechanism: pepper compounds might act on the TRPV1 receptor","quote":"It was found that these effects are owing to the bio‐active profile of black pepper, such as isopiperine, isochavicine, piperine, piperanine, piperolein A and B, which might act on receptor TRPV1"}},{"kind":"proposed","fact":{"id":"glp1","kind":"statement","label":"TRPV1 activation raises GLP-1 in the lower small intestine and the blood (earlier work the authors cite)","quote":"Furthermore, TRPV1 activation increases GLP‐1; glucagon‐like peptide‐1 levels in the ileum and plasma."}},{"kind":"proposed","fact":{"id":"trpv1_mouth","kind":"statement","label":"TRPV1 is in the mouth; the authors say its activation is known to affect glucose control and appetite","quote":"TRPV1 is present in the oral cavity and its activation is widely known to improve glucose homeostasis, potentially affect appetite responses as well as increase energy metabolism."}}],"meal":{"dose":{"text":"1 g","ref":"in_egg"},"words":"of black pepper, mixed into the egg"},"blood":{"lead":"Blood sugar:","signal":"lower than after the plain egg","kind":"measured","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}},"when":{"lead":"The clear difference: at","minutes":{"n":30,"ref":"glucose_30"},"unit":"minutes","kind":"measured","fact":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal; the paper does not say by how much","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}}},"trial":{"words":"What the trial showed","kind":"measured","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}},"idea":"The authors'' idea. No hormones were measured.","measured":"Measured"}}},"protocol":{"paragraphs":[[{"text":"The trial tested one dose: 1 g of black pepper, mixed into a fried egg.","refs":["in_egg"]},{"text":"The egg came with 2 slices of toast and a cup of sweet milk tea.","refs":["plate"]},{"text":"The participants ate after an overnight fast and finished within 10 minutes.","refs":["fast","eaten_in"]}],[{"text":"A second version added 1 g of turmeric to the pepper.","refs":["meals"]},{"text":"It showed the same early glucose difference, and tasters liked it more than pepper alone.","refs":["glucose_30","taste_rank"]},{"text":"Turmeric without pepper showed no clear difference in glucose.","refs":["turmeric_none"]}],[{"text":"Each version was eaten once.","refs":["single_meal","washout"]},{"text":"The trial did not test a daily habit.","refs":["lim_long_term"]}]],"figure":{"figure":"first-half-hour","headline":[{"text":"With pepper, blood sugar was lower.","refs":["glucose_lower"]},{"text":"The clear difference was at 30 minutes; across 3 hours, no clear difference.","refs":["glucose_30","glucose_total","nothing_else"]}],"caption":[{"text":"Dotted lines: a sketch of the shape, not data.","refs":[]},{"text":"The dots are when blood sugar was checked, and the shaded column is the one clear difference.","refs":["timepoints","glucose_30"]}],"alt":"Two dotted lines rise after breakfast, peak and settle, one for the plain egg and one for the egg with black pepper. They part only around the 30-minute reading, where a shaded column says the clear difference was, and run together after it. A bracket over all five readings, from the meal to 180 minutes, says the whole 3 hours showed no clear difference. The paper prints no blood sugar values, so the size of the gap is not from the paper.","params":{"title":"Blood sugar after breakfast: a sketch of the shape over the measured readings","curves":{"sketch":"blood-sugar-wave","concept":"post-meal-blood-sugar","tag":"Sketch, not data","ink":"ink","labels":{"plain":"Plain egg","pepper":"Egg with pepper","both":"Egg with pepper and turmeric","turmeric":"Plain egg and egg with turmeric"},"alt":"Dotted lines that climb after a meal, peak and ebb: a sketch of the shape of blood sugar after eating, not data. Their heights and the gap between them are not from the paper."},"times":[{"n":0,"ref":"timepoints"},{"n":30,"ref":"timepoints"},{"n":60,"ref":"timepoints"},{"n":120,"ref":"timepoints"},{"n":180,"ref":"timepoints"}],"unit":"min","start":"Meal","column":{"label":"Clear difference here","kind":"measured","fact":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal; the paper does not say by how much","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}},"at":{"n":30,"ref":"glucose_30"}},"bracket":{"lead":"Whole","n":{"n":3,"ref":"nothing_else"},"rest":"hours: no clear difference","still":"The whole time: no clear difference","kind":"measured","fact":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"dots":{"label":"Blood sugar was checked at these times"},"phases":["eat","the first rise","settling"],"notes":{"shape":"The paper prints no blood sugar values, so the lines show shape only.","people":{"n":{"n":20,"ref":"sample"},"rest":"healthy adults, one meal each way."}},"switches":{"legend":"What is in your egg? Pick to see that meal.","pepper":"Black pepper","turmeric":"Turmeric"},"results":{"plain":"This is the plain meal the others were compared with.","pepper":{"words":"After this meal, blood sugar was lower than after the plain egg.","kind":"measured","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}},"at":{"lead":"The clear difference was at","n":{"n":30,"ref":"glucose_30"},"rest":"minutes."},"total":{"lead":"Over","n":{"n":3,"ref":"nothing_else"},"rest":"hours: no clear difference."}},"turmeric":{"words":"Turmeric alone: no clear difference in blood sugar from the plain egg.","kind":"measured","fact":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no clear difference in blood glucose from the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}}},"sugar":{"lead":"This meal’s tea had more sugar:","more":{"n":10,"ref":"sugar_row"},"mid":"g, not","less":{"n":8,"ref":"sugar_row"},"end":"g."}}}}},"audit":{"effect":[{"text":"The paper''s text gives no size for the glucose difference.","refs":["glucose_30"]},{"text":"It says only that the two pepper meals differed from the plain meal at 30 minutes, with p = .023.","refs":["glucose_30"]}],"weakEnd":[{"text":"The paper reports no confidence interval for any glucose result.","refs":["glucose_30"]},{"text":"The gap could be wide or barely there; the text cannot say.","refs":["glucose_30"]},{"text":"Over the full 3 hours, total blood glucose did not differ between the four meals.","refs":["glucose_total","nothing_else"]}],"limitations":[[{"text":"The trial measured no hormones.","refs":["lim_hormones"]},{"text":"The sensor-and-hormone story is the authors'' idea, not a result.","refs":["lim_hormones","lim_mechanism"]}],[{"text":"Hunger and fullness were self-reported on paper scales.","refs":["appetite_scale"]},{"text":"The authors say the lower hunger might come from the spiced meals tasting worse.","refs":["lim_taste"]}],[{"text":"One breakfast per version, in 20 young adults: nothing here speaks to long-term use.","refs":["single_meal","sample","ages","lim_long_term"]}]],"missed":[{"text":"The easy summary: these spices are good for blood sugar.","refs":[]},{"text":"The paper found no clear difference in glucose for turmeric alone.","refs":["turmeric_none"]},{"text":"The 3-hour total did not differ for any meal.","refs":["glucose_total","nothing_else"]},{"text":"Only healthy people took part, so the trial cannot speak to diabetes.","refs":["criteria","sample"]}],"more":[[{"text":"The paper does not say whether the participants knew which meal they had.","refs":[]}],[{"text":"The ingredient table lists 10 g of sugar for the combined meal and 8 g for the others.","refs":["sugar_row"]},{"text":"It still gives all four the same 50 g of carbohydrate.","refs":["carb_row"]}],[{"text":"Overall taste scores out of 9: plain 6.5, pepper 6.2, turmeric 6.1, both spices 6.6.","refs":["taste_scale","taste_c","taste_bp","taste_tr","taste_both"]}],[{"text":"Stomach and gut symptoms, also self-rated, did not differ between meals.","refs":["gut","gut_scale"]}],[{"text":"The authors name one weakness: they never measured the meals'' glycemic index.","refs":["lim_stated"]}]],"figure":{"figure":"five-readings","caption":[{"text":"One dot per reading.","refs":["timepoints"]},{"text":"Orange: differed from the plain meal.","refs":["glucose_30"]}],"alt":"Four rows of five dots, one row for each meal. The readings were at 0, 30, 60, 120 and 180 minutes. At 30 minutes, the pepper meal and the both-spices meal are marked as differing from the plain meal. A bracket over all five readings says the total showed no difference.","params":{"times":[{"n":0,"ref":"timepoints"},{"n":30,"ref":"timepoints"},{"n":60,"ref":"timepoints"},{"n":120,"ref":"timepoints"},{"n":180,"ref":"timepoints"}],"unit":"min","meals":[{"label":"Plain","differed":[],"reading":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"}},{"label":"Pepper","differed":[{"n":30,"ref":"glucose_30"}],"reading":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"}},{"label":"Turmeric","differed":[],"reading":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no clear difference in blood glucose from the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}}},{"label":"Both spices","differed":[{"n":30,"ref":"glucose_30"}],"reading":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"}}],"early":{"kind":"measured","fact":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal; the paper does not say by how much","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}},"at":{"n":30,"ref":"glucose_30"}},"total":{"kind":"measured","fact":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}}}}}},"glossary":[{"term":"randomized","plain":"Chance decided the order of the meals, not the people running the trial.","refs":["crossover"],"concept":null},{"term":"TRPV1","plain":"A sensor found in the mouth.","refs":["trpv1_mouth"],"concept":null},{"term":"GLP-1","plain":"A hormone the gut releases after a meal. It helps hold down the rise in blood sugar after eating, slows the gut and curbs appetite.","refs":[],"concept":"glucagon-like-peptide"},{"term":"piperine","plain":"The main active ingredient of black pepper.","refs":["piperine"],"concept":null},{"term":"blood glucose","plain":"The sugar carried in the blood, measured here from a finger prick.","refs":["finger_prick"],"concept":null}],"primaryEstimate":"glucose_30","finding":{"question":[{"text":"Does black pepper in your breakfast egg change your blood sugar?","refs":["in_egg"]}],"headline":[{"text":"Blood sugar was lower after the pepper meals than after the plain meal.","refs":["glucose_lower"]},{"text":"The clear difference was at 30 minutes;","refs":["glucose_30"]},{"text":"across 3 hours, no clear difference.","refs":["glucose_total","nothing_else"]}],"support":[{"text":"The paper doesn''t say by how much.","refs":["glucose_lower"]}]},"simulator":{"kind":"breakfast-meals","params":{"participants":{"n":20,"ref":"sample"},"earlyMinutes":{"n":30,"ref":"glucose_30"},"totalMinutes":{"n":180,"ref":"timepoints"},"tasteMax":{"n":9,"ref":"taste_scale"},"meals":[{"id":"plain","label":"Plain egg and toast","added":"Nothing added. Every other meal is compared with this one.","glucoseEarly":{"result":"reference","fact":null},"glucoseTotal":{"result":"reference","fact":null},"hunger":{"result":"reference","fact":null},"gut":{"result":"reference","fact":null},"taste":{"n":6.5,"ref":"taste_c"}},{"id":"pepper","label":"With black pepper","added":"Black pepper in the egg, at the dose the trial tested.","glucoseEarly":{"result":"lower","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}},"glucoseTotal":{"result":"same","fact":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"hunger":{"result":"lower","fact":{"id":"appetite","kind":"finding","label":"less hunger and less perceived eating ability, more satiety, after the pepper meal and the pepper-plus-turmeric meal; no sizes given","quote":"A decrease in perceived eating ability and hunger, and an increase in satiety after BP + TR and BP meal was observed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated hunger, satiety and how much they felt they could eat","tier":"low"}}},"gut":{"result":"same","fact":{"id":"gut","kind":"finding","label":"no clear difference between meals or over time","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}}},"taste":{"n":6.2,"ref":"taste_bp"}},{"id":"turmeric","label":"With turmeric","added":"Turmeric in the egg, at the dose the trial tested.","glucoseEarly":{"result":"same","fact":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no clear difference in blood glucose from the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}}},"glucoseTotal":{"result":"same","fact":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"hunger":{"result":"none_reported","fact":null},"gut":{"result":"same","fact":{"id":"gut","kind":"finding","label":"no clear difference between meals or over time","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}}},"taste":{"n":6.1,"ref":"taste_tr"}},{"id":"both","label":"With both spices","added":"Black pepper and turmeric together in the egg.","glucoseEarly":{"result":"lower","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}},"glucoseTotal":{"result":"same","fact":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"hunger":{"result":"lower","fact":{"id":"appetite","kind":"finding","label":"less hunger and less perceived eating ability, more satiety, after the pepper meal and the pepper-plus-turmeric meal; no sizes given","quote":"A decrease in perceived eating ability and hunger, and an increase in satiety after BP + TR and BP meal was observed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated hunger, satiety and how much they felt they could eat","tier":"low"}}},"gut":{"result":"same","fact":{"id":"gut","kind":"finding","label":"no clear difference between meals or over time","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}}},"taste":{"n":6.6,"ref":"taste_both"}}]}},"glance":{"figure":{"figure":"first-half-hour","headline":[{"text":"With pepper, blood sugar was lower.","refs":["glucose_lower"]},{"text":"The clear difference was at 30 minutes; across 3 hours, no clear difference.","refs":["glucose_30","glucose_total","nothing_else"]}],"caption":[],"alt":"Two dotted lines rise after breakfast and settle; they part only in one shaded column early on, where the clear difference was.","params":{"title":"Blood sugar after breakfast: a sketch of the shape over the measured readings","curves":{"sketch":"blood-sugar-wave","concept":"post-meal-blood-sugar","tag":"Sketch, not data","ink":"ink","labels":{"plain":"Plain egg","pepper":"Egg with pepper","both":"Egg with pepper and turmeric","turmeric":"Plain egg and egg with turmeric"},"alt":"Dotted lines that climb after a meal, peak and ebb: a sketch of the shape of blood sugar after eating, not data. Their heights and the gap between them are not from the paper."},"times":[{"n":0,"ref":"timepoints"},{"n":30,"ref":"timepoints"},{"n":60,"ref":"timepoints"},{"n":120,"ref":"timepoints"},{"n":180,"ref":"timepoints"}],"unit":"min","start":"Meal","column":{"label":"Clear difference here","kind":"measured","fact":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal; the paper does not say by how much","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}},"at":{"n":30,"ref":"glucose_30"}},"bracket":{"lead":"Whole","n":{"n":3,"ref":"nothing_else"},"rest":"hours: no clear difference","still":"The whole time: no clear difference","kind":"measured","fact":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"dots":{"label":"Blood sugar was checked at these times"},"phases":["eat","the first rise","settling"],"notes":{"shape":"The paper prints no blood sugar values, so the lines show shape only.","people":{"n":{"n":20,"ref":"sample"},"rest":"healthy adults, one meal each way."}},"switches":{"legend":"What is in your egg? Pick to see that meal.","pepper":"Black pepper","turmeric":"Turmeric"},"results":{"plain":"This is the plain meal the others were compared with.","pepper":{"words":"After this meal, blood sugar was lower than after the plain egg.","kind":"measured","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}},"at":{"lead":"The clear difference was at","n":{"n":30,"ref":"glucose_30"},"rest":"minutes."},"total":{"lead":"Over","n":{"n":3,"ref":"nothing_else"},"rest":"hours: no clear difference."}},"turmeric":{"words":"Turmeric alone: no clear difference in blood sugar from the plain egg.","kind":"measured","fact":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no clear difference in blood glucose from the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}}},"sugar":{"lead":"This meal’s tea had more sugar:","more":{"n":10,"ref":"sugar_row"},"mid":"g, not","less":{"n":8,"ref":"sugar_row"},"end":"g."}}}},"x":[{"text":"Time after breakfast","refs":[]}],"y":[],"alt":[{"text":"Two dotted lines rise after breakfast and settle; they part only in one shaded column early on, where the clear difference was.","refs":["glucose_30"]}],"note":[{"text":"Line shapes are a sketch; the readings are from the study. Try it with your own egg inside.","refs":[]}],"tryIt":[{"text":"pick what is in your egg","refs":[]}]},"sourceLine":"20 healthy adults · randomized crossover trial · four breakfasts each","facts":{"ages":{"id":"ages","kind":"context","label":"Average age, body mass index and fasting blood glucose of the people who actually took part","quote":"The mean age of female students was 21.4 ± 0.72 years with a mean BMI of 23.5 ± 3.9 and fasting blood glucose of 73.5 ± 9.05 mg/dL. For boys the mean age was 21.9 ± 0.84, BMI was 23.22 ± 5.7, and fasting blood glucose was 77.35 ± 9.57 mg/dL."},"appetite":{"id":"appetite","kind":"finding","label":"less hunger and less perceived eating ability, more satiety, after the pepper meal and the pepper-plus-turmeric meal; no sizes given","quote":"A decrease in perceived eating ability and hunger, and an increase in satiety after BP + TR and BP meal was observed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated hunger, satiety and how much they felt they could eat","tier":"low"}},"appetite_scale":{"id":"appetite_scale","kind":"context","label":"Appetite was rated by the participants on 100 mm lines","quote":"Appetite was assessed by using VAS (Flint et al., ). The VAS consisted of four scales, each of 100 mm length, which was used to determine the participant''s hunger from 0 to 100 mm"},"carb_row":{"id":"carb_row","kind":"context","label":"Table 1 gives all four meals the same carbohydrate total","quote":"Average CHO (g) | 50 | 50 | 50 | 50 |"},"criteria":{"id":"criteria","kind":"context","label":"Who could take part: age, body mass index, no chronic disease","quote":"Inclusion criteria were: free from chronic diseases, aged 18–60 years, and healthy individual with body mass index (BMI) (18.5–24.9 kg/m2) medically healthy."},"crossover":{"id":"crossover","kind":"context","label":"Design: randomized crossover, four test meals, each with 50 g of carbohydrate","quote":"The study made use of a randomized crossover design; all the subjects were provided with 04 test foods, all have 50 g carbohydrate content."},"eaten_in":{"id":"eaten_in","kind":"context","label":"Meal eaten within 10 minutes","quote":"Next, the test meals, supplying 50 g of accessible carbohydrates, were ingested in 10 min."},"fast":{"id":"fast","kind":"context","label":"Overnight fast before each visit","quote":"Selected personnel were instructed to take their twilight meal up to 10:00 p.m. following which they were asked to fast"},"finger_prick":{"id":"finger_prick","kind":"context","label":"Blood glucose measured with a glucometer from a finger prick","quote":"was employed to compute the blood glucose, and samples were collected via finger prick"},"glp1":{"id":"glp1","kind":"statement","label":"TRPV1 activation raises GLP-1 in the lower small intestine and the blood (earlier work the authors cite)","quote":"Furthermore, TRPV1 activation increases GLP‐1; glucagon‐like peptide‐1 levels in the ileum and plasma."},"glucose_30":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal; the paper does not say by how much","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}},"glucose_lower":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal; direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}},"glucose_total":{"id":"glucose_total","kind":"finding","label":"no clear difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}},"gut":{"id":"gut","kind":"finding","label":"no clear difference between meals or over time","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}},"gut_scale":{"id":"gut_scale","kind":"context","label":"Gut symptoms were rated by the participants on a 4-point scale","quote":"Gastrointestinal symptoms such as swelling of stomach, uneasy feelings, flatulence, loose stools, diarrhea, constipation, cramping, and grumbling were assessed using a 4‐point Likert scale."},"in_egg":{"id":"in_egg","kind":"context","label":"How the spice was given: powder mixed into the fried egg","quote":"In test meals black pepper (1 g) and turmeric powder (1 g) were added to the egg."},"lim_hormones":{"id":"lim_hormones","kind":"limitation","label":"The proposed mechanism was not measured: no hormones were examined","quote":"However, hormones involved in the regulation of satiety were not examined in this intervention."},"lim_long_term":{"id":"lim_long_term","kind":"limitation","label":"No long-term data: the authors call for long-term studies","quote":"Future long‐term studies with increased dosage of turmeric and black pepper are considered necessary to understand the advantages of long‐term utilization of turmeric and black pepper supplemented breakfast"},"lim_mechanism":{"id":"lim_mechanism","kind":"limitation","label":"The authors say the mechanisms still need investigating","quote":"The potential components of turmeric and black pepper and actual physiological mechanisms involved in these effects need further investigation."},"lim_stated":{"id":"lim_stated","kind":"limitation","label":"The authors'' own stated limitation: the glycemic index of the meals was not measured","quote":"This study has some deficiencies. The glycemic index of the test meals was not noted and it necessitates the need to be explored in future research studies."},"lim_taste":{"id":"lim_taste","kind":"limitation","label":"The drop in hunger may be a taste effect: the spiced meals were liked less","quote":"The reported reduction in hunger after BP and BP + TR meal consumption might be because of decreased palatability since different scientific approaches have revealed an enormous effect of palatability on appetite"},"meals":{"id":"meals","kind":"context","label":"The four test meals and the spice doses","quote":"Test foods were: (1) bread toast and egg (control diet), (2) bread toast and egg +1 g black pepper (BP), (3) bread toast and egg +1 g turmeric (TR), and (4) bread toast and egg +1 g black pepper +1 g turmeric (BP + TR), all meals were served with tea."},"nothing_else":{"id":"nothing_else","kind":"context","label":"No other food or drink for the 3 hours","quote":"The ingestion of any kind of food or beverage during the period of 3 h was precluded"},"piperine":{"id":"piperine","kind":"context","label":"Black pepper''s main active ingredient is piperine","quote":"Black pepper (Piper nigrum) family piperaceae, with the main active ingredient piperine, has a hypoglycaemic effect (Panda & Kar, )."},"plate":{"id":"plate","kind":"context","label":"What else was on the plate: two toasts and a cup of sweet milk tea","quote":"The fried egg was served with 2 standard bread toasts and a cup of black tea (250 mL) having 200 mL milk, 50 mL water, 1 teaspoon black tea (5 g), and 1 tablespoon sugar (8 g)."},"sample":{"id":"sample","kind":"context","label":"Number and sex of participants","quote":"For this study, a total of 20 healthy individuals comprising 10 males and 10 females, were enrolled through direct personal communication."},"single_meal":{"id":"single_meal","kind":"context","label":"The authors call this an acute intervention (one meal per condition)","quote":"The decrease in hunger and perceived eating ability and increase in satiety and fullness after BP + TR and BP meal in this acute intervention"},"sugar_row":{"id":"sugar_row","kind":"context","label":"Table 1 lists 10 g of sugar for the combined meal and 8 g for the other three","quote":"Sugar (g) | 08 | 08 | 08 | 10 |"},"taste_both":{"id":"taste_both","kind":"estimate","label":"Overall pleasantness of the pepper-plus-turmeric meal, mean ± SD on the 9-point scale (Table 3)","quote":"BP + TR | 6.5 ± 0.49b\n| 6.2 ± 0.52b\n| 6.2 ± 0.46b\n| 6.5 ± 0.44b\n| 6.6 ± 0.42b","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Overall pleasantness rating of the pepper-plus-turmeric meal (9-point scale)","measure":"mean","point":6.6,"ciLow":null,"ciHigh":null,"unit":"points","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":0.42}},"taste_bp":{"id":"taste_bp","kind":"estimate","label":"Overall pleasantness of the black pepper meal, mean ± SD on the 9-point scale (Table 3)","quote":"BP | 5.9 ± 0.55a\n| 5.35 ± 0.61a\n| 6.05 ± 0.58ab\n| 5.9 ± 0.55a\n| 6.2 ± 0.50a","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Overall pleasantness rating of the black pepper meal (9-point scale)","measure":"mean","point":6.2,"ciLow":null,"ciHigh":null,"unit":"points","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":0.5}},"taste_c":{"id":"taste_c","kind":"estimate","label":"Overall pleasantness of the plain (control) meal, mean ± SD on the 9-point scale (Table 3)","quote":"C | 6.3 ± 0.48b\n| 6.4 ± 0.46b\n| 5.5 ± 0.51a\n| 6.7 ± 0.48b\n| 6.5 ± 0.39ab","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Overall pleasantness rating of the plain (control) meal (9-point scale)","measure":"mean","point":6.5,"ciLow":null,"ciHigh":null,"unit":"points","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":0.39}},"taste_rank":{"id":"taste_rank","kind":"finding","label":"the control meal and the combined meal were rated higher than the pepper-only and turmeric-only meals, a clear difference","quote":"Post hoc pair‐wise comparison shows that the control meal and combined meal have significantly (p < .05) higher acceptability than (BP and TR) meal in comparison of general appearance, consistency, smell, taste, and whole pleasantness.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Palatability (appearance, texture, smell, taste, overall pleasantness)","tier":"low"}},"taste_scale":{"id":"taste_scale","kind":"context","label":"Taste was rated on a 9-point scale from dislike extremely to like extremely","quote":"A 9‐point hedonic calibration was exploited with dislike extremely on one end and like extremely on the other end."},"taste_tr":{"id":"taste_tr","kind":"estimate","label":"Overall pleasantness of the turmeric meal, mean ± SD on the 9-point scale (Table 3)","quote":"TR | 5.7 ± 0.48a\n| 5.5 ± 0.47a\n| 5.6 ± 0.533a\n| 5.9 ± 0.47a\n| 6.1 ± 0.40a","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","estimate":{"outcome":"Overall pleasantness rating of the turmeric meal (9-point scale)","measure":"mean","point":6.1,"ciLow":null,"ciHigh":null,"unit":"points","absolute":true,"tier":"low"},"spread":{"kind":"sd","value":0.4}},"timepoints":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"},"trpv1":{"id":"trpv1","kind":"statement","label":"Authors'' proposed mechanism: pepper compounds might act on the TRPV1 receptor","quote":"It was found that these effects are owing to the bio‐active profile of black pepper, such as isopiperine, isochavicine, piperine, piperanine, piperolein A and B, which might act on receptor TRPV1"},"trpv1_mouth":{"id":"trpv1_mouth","kind":"statement","label":"TRPV1 is in the mouth; the authors say its activation is known to affect glucose control and appetite","quote":"TRPV1 is present in the oral cavity and its activation is widely known to improve glucose homeostasis, potentially affect appetite responses as well as increase energy metabolism."},"turmeric_dose":{"id":"turmeric_dose","kind":"statement","label":"Authors'' guess at why turmeric alone showed no clear difference: the dose was low","quote":"A possible rationale for this may be the use of low dose of turmeric powder in this study."},"turmeric_none":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no clear difference in blood glucose from the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","why":"People were assigned at random, but only 20 took part, so a bigger trial could change the picture.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}},"washout":{"id":"washout","kind":"context","label":"Each person ate all four meals, one per visit, a week apart","quote":"Every subject attended four sessions with 1 week washout period between the trials."}},"context":{"studies":[],"concepts":[{"slug":"glucagon-like-peptide","term":"glucagon-like peptide","plain":"A hormone the gut releases after a meal. It helps hold down the rise in blood sugar after eating, slows the gut and curbs appetite.","model":"The gut''s message that food has arrived: deal with the sugar, slow the conveyor, stop asking for more.","reference":{"doi":"10.1152/physrev.00034.2006","title":"The physiology of glucagon-like peptide 1"}},{"slug":"post-meal-blood-sugar","term":"blood sugar after a meal","plain":"After you eat, sugar from the food passes from the gut into the blood, so the level rises. The body then moves that sugar into muscle and other cells, and the level falls back towards where it started.","model":"A wave after each meal: it climbs as the food is absorbed, peaks, then ebbs as the body tucks the sugar away.","reference":{"doi":"10.1177/193229680700100513","title":"Continuous glucose profiles in healthy subjects under everyday life conditions and after different meals"}}]}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('735a2dc7-8f80-59f4-afae-c49e591ae748', 'key_takeaways', '{"takeaways":[[{"text":"The dose tested was 1 g of black pepper, cooked into the egg of a toast-and-tea breakfast.","refs":["in_egg","plate"]}],[{"text":"The glucose difference showed 30 minutes after eating and not in the 3-hour total.","refs":["glucose_30","glucose_total","nothing_else"]}],[{"text":"Turmeric alone, at 1 g, showed no clear difference in glucose.","refs":["turmeric_none"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('153827fc-001f-5428-ab08-1d5e6da2d9cc', '735a2dc7-8f80-59f4-afae-c49e591ae748', 1, '1 g of black pepper in my breakfast', 'The dose this trial tested, cooked into an egg. It did not test more, less or other meals.', 'action', 'low', 'Blood glucose 30 minutes after the meal: differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal; the paper does not say by how much', null, null, null, null, null, null),
  ('72924d31-4867-5fbd-a568-8b5059af38f4', '735a2dc7-8f80-59f4-afae-c49e591ae748', 2, '1 g of turmeric with the pepper', 'Tested together with pepper. Turmeric alone showed no glucose effect, so this carries no weight.', 'action', 'none', null, null, null, null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;
